// Flashcards, written questions and R questions — add new content here
const CARDS_BASE = [
  // CM1A — Theory of interest rates
  {module:'CM1A',sub:'int-force',color:'#3D6FD1',topic:'Theory of interest rates',q:'How is the force of interest δ related to the effective annual rate of interest i?',a:'δ = ln(1 + i), equivalently 1 + i = e^δ. It is the continuously-compounded equivalent of i.'},
  {module:'CM1A',sub:'int-rates',color:'#3D6FD1',topic:'Theory of interest rates',q:'How do you convert a nominal rate of interest i^(p) payable p-thly per year to an effective annual rate i?',a:'(1 + i) = (1 + i^(p)/p)^p. Divide the nominal rate by p, add 1, raise to the power p.'},
  {module:'CM1A',sub:'int-tvm',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is the present value of £1 due in n years at effective annual interest rate i?',a:'v^n = (1+i)^{−n}, where v = 1/(1+i) is the discount factor.'},
  {module:'CM1A',sub:'int-inf',color:'#3D6FD1',topic:'Theory of interest rates',q:'If the money rate of interest is i and the inflation rate is f, what is the real rate of interest r?',a:'(1 + r) = (1 + i)/(1 + f), so r ≈ i − f for small rates.'},
  {module:'CM1A',sub:'int-ann',color:'#3D6FD1',topic:'Theory of interest rates',q:'Write down the present value of an annuity-certain of £1 per year for n years (payable annually in arrear).',a:'ä_{n|} = (1 − v^n)/i, where v = 1/(1+i).'},
  {module:'CM1A',sub:'int-duration',color:'#3D6FD1',topic:'Theory of interest rates',q:"State Redington's three conditions for immunisation.",a:"(1) PV assets = PV liabilities. (2) Duration of assets = duration of liabilities. (3) Convexity of assets > convexity of liabilities."},
  {module:'CM1A',sub:'int-term',color:'#3D6FD1',topic:'Theory of interest rates',q:'How is the n-year spot rate s_n related to forward rates?',a:'(1 + s_n)^n = (1 + f_{0,1})(1 + f_{1,2})…(1 + f_{n−1,n}), i.e. the spot accumulation equals the product of successive one-year forward accumulations.'},
  {module:'CM1A',sub:'int-pv',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is the present value of a continuous cashflow ρ(t) paid at rate ρ(t) between times 0 and T?',a:'PV = ∫₀ᵀ ρ(t) · e^{−δt} dt, where δ is the force of interest (assumed constant).'},
  // CM1A — Equation of value
  {module:'CM1A',sub:'eqv-basic',color:'#3D6FD1',topic:'Equation of value',q:'What does an equation of value state?',a:'At a given rate, the present value of the incoming cashflows equals the present value of the outgoing cashflows.'},
  {module:'CM1A',sub:'eqv-bonds',color:'#3D6FD1',topic:'Equation of value',q:'For a fixed-interest bond with coupon rate r%, face value F, redemption value C, and n years to redemption, write the price P at yield i.',a:'P = F·r/100 · a_{n|i} + C · v^n, where a_{n|i} is the annuity factor and v = 1/(1+i).'},
  {module:'CM1A',sub:'eqv-proj',color:'#3D6FD1',topic:'Equation of value',q:'Define the Internal Rate of Return (IRR) of a project.',a:'The IRR is the rate of interest at which the NPV of all cashflows (inflows and outflows) equals zero.'},
  {module:'CM1A',sub:'eqv-loan',color:'#3D6FD1',topic:'Equation of value',q:'For a flat loan repaid by level instalments, what fraction of each instalment is interest vs capital in the first period?',a:'Interest = i × (outstanding loan); capital = instalment − interest. The interest portion is highest early on and declines over time.'},
  {module:'CM1A',sub:'eqv-shares',color:'#3D6FD1',topic:'Equation of value',q:'Under the dividend discount model with constant dividend growth rate g, what is the price of a share paying dividend D next year at required return k?',a:'P = D / (k − g), provided k > g.'},
  // CM1B — Decrement models
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'Express ₙpₓ in terms of the force of mortality μ.',a:'ₙpₓ = exp(−∫₀ⁿ μₓ₊ₜ dt). It is the probability of a life aged x surviving n more years.'},
  {module:'CM1B',sub:'dec-multi',color:'#3D6FD1',topic:'Decrement models',q:'What does the probability n|m qx represent?',a:'The probability that a life aged x survives n years and then dies within the following m years.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What is the difference between a whole-life assurance and a term assurance?',a:'A whole-life assurance pays a benefit on death whenever it occurs. A term assurance pays only if death occurs within a specified period n; otherwise nothing is paid.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'Write the EPV (expected present value) of a whole-life assurance of £1 payable at the end of the year of death, using actuarial notation.',a:'A_x = Σ_{k=0}^{∞} v^{k+1} · k|qₓ, where v = 1/(1+i) and k|qₓ is the probability of dying in year k+1.'},
  {module:'CM1B',sub:'dec-markov',color:'#3D6FD1',topic:'Decrement models',q:'In a multi-state Markov model, what do the Kolmogorov forward equations describe?',a:'They give the rate of change of transition probabilities ₜp_{ij} as a function of transition intensities, allowing us to compute the probability of being in any state at time t.'},
  {module:'CM1B',sub:'dec-mdt',color:'#3D6FD1',topic:'Decrement models',q:'In a multiple decrement table with decrements from cause j, how is the dependent decrement rate q\'_x^(j) related to the independent rate qₓ^(j)?',a:"q'_x^(j) ≈ qₓ^(j) · (1 − ½ Σ_{k≠j} qₓ^(k)) under the UDD assumption — the dependent rate is the independent rate reduced by the probability of earlier decrement from another cause."},
  // CM1B — Pricing and reserving
  {module:'CM1B',sub:'res-grossprem',color:'#3D6FD1',topic:'Pricing & reserving',q:'State the equivalence principle for premium calculation.',a:'The gross premium P is set so that E[PV of outgo] = E[PV of income] at the valuation rate, i.e. the expected profit is zero at outset.'},
  {module:'CM1B',sub:'res-reserve',color:'#3D6FD1',topic:'Pricing & reserving',q:'Give the recursive relationship between successive reserves in words.',a:'(Opening reserve + premium) accumulated with interest, less expected benefits & expenses, divided by the survival probability = closing reserve.'},
  {module:'CM1B',sub:'res-equiv',color:'#3D6FD1',topic:'Pricing & reserving',q:'When do the prospective and retrospective reserves give the same value?',a:'When the valuation basis equals the premium basis — i.e. when reserves and premiums are computed at the same interest rate and mortality table.'},
  {module:'CM1B',sub:'res-mortality',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the death strain at risk (DSAR) for a policy in year t.',a:'DSAR = (benefit payable on death) − (reserve released on death) = S − ₁V. It represents the net amount at risk if a policyholder dies.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'In profit testing, what is the profit vector for year t?',a:'PRO_t = (₁V_{t−1} + P_t − e_t)(1+i) − q_{x+t−1}(S_t + E_t) − p_{x+t−1} · ₁V_t, i.e. income accumulated with interest less expected outgo.'},
  {module:'CM1B',sub:'res-unitlinked',color:'#3D6FD1',topic:'Pricing & reserving',q:'Why are non-unit reserves (sterling reserves) needed for unit-linked contracts?',a:'To cover future negative non-unit cashflows (e.g. guarantee costs, expense charges insufficient to cover expenses). They must be non-negative to avoid a future strain; zeroisation ensures this.'},
  // CS1A — Data analysis
  {module:'CS1A',sub:'data-corr',color:'#2E9C8E',topic:'Data analysis',q:"What does Spearman's rank correlation coefficient measure?",a:'The strength and direction of the monotonic (not necessarily linear) relationship between two variables, computed on their ranks.'},
  {module:'CS1A',sub:'data-pca',color:'#2E9C8E',topic:'Data analysis',q:'What does a scree plot show in PCA?',a:'The eigenvalues (variance explained) of each principal component in decreasing order. A "kink" or "elbow" helps decide how many components to retain.'},
  {module:'CS1A',sub:'data-explore',color:'#2E9C8E',topic:'Data analysis',q:'Name three graphical tools used in exploratory data analysis.',a:'Histogram (distribution shape), boxplot (median, quartiles, outliers), scatter plot (relationships between two variables).'},
  // CS1A — Random variables
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'State the mean and variance of a Poisson(λ) distribution.',a:'Mean = λ, Variance = λ. The Poisson is the unique distribution where mean equals variance.'},
  {module:'CS1A',sub:'rv-joint',color:'#2E9C8E',topic:'Random variables',q:'Define the covariance of X and Y and state when it equals zero.',a:'Cov(X,Y) = E[XY] − E[X]E[Y]. It equals zero when X and Y are uncorrelated; independence implies zero covariance, but not vice versa.'},
  {module:'CS1A',sub:'rv-condexp',color:'#2E9C8E',topic:'Random variables',q:'State the law of total expectation.',a:'E[X] = E[E[X|Y]], i.e. the unconditional expectation equals the expectation of the conditional expectation over all values of Y.'},
  {module:'CS1A',sub:'rv-gf',color:'#2E9C8E',topic:'Random variables',q:'What is the moment generating function (MGF) of X and how is it used to find E[X²]?',a:'M(t) = E[e^{tX}]. Then E[X^r] = M^{(r)}(0), the r-th derivative of M(t) evaluated at t = 0.'},
  {module:'CS1A',sub:'rv-clt',color:'#2E9C8E',topic:'Random variables',q:'State the Central Limit Theorem informally.',a:'For iid variables with finite variance, the sample mean tends to Normal(μ, σ²/n) as n → ∞.'},
  {module:'CS1A',sub:'rv-sampling',color:'#2E9C8E',topic:'Random variables',q:'If X₁,…,Xₙ ~ N(μ,σ²) iid, what is the distribution of (n−1)S²/σ²?',a:'Chi-squared with (n−1) degrees of freedom, where S² is the sample variance. It is independent of the sample mean X̄.'},
  // CS1A — Statistical inference
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'When is an estimator θ̂ said to be unbiased?',a:'When E[θ̂] = θ for every possible value of θ — it is correct on average.'},
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'State the Cramér-Rao lower bound.',a:'Var(θ̂) ≥ 1 / I(θ), where I(θ) = −E[∂²ln L/∂θ²] is the Fisher information. An estimator achieving this bound is efficient.'},
  {module:'CS1A',sub:'inf-ci',color:'#2E9C8E',topic:'Statistical inference',q:'How is a 95% confidence interval for a population mean interpreted?',a:'If the procedure were repeated many times, 95% of the resulting intervals would contain the true mean. It is NOT the probability that this particular interval contains μ.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'What is a p-value?',a:'The probability of observing a test statistic at least as extreme as the one obtained, given that H₀ is true. A small p-value is evidence against H₀.'},
  // CS1A — Regression theory (R implementation flashcards are in CS1B section below)
  {module:'CS1A',sub:'reg-lm',color:'#2E9C8E',topic:'Regression',q:'State the OLS estimator for β in the multiple linear regression model Y = Xβ + ε.',a:'β̂ = (X^T X)^{−1} X^T Y, assuming X has full column rank.'},
  {module:'CS1A',sub:'reg-diag',color:'#2E9C8E',topic:'Regression',q:"What does Cook's distance measure in regression diagnostics?",a:"The influence of observation i on all fitted values — it combines leverage and residual size. Large Cook's distance suggests a highly influential point."},
  {module:'CS1A',sub:'reg-glm',color:'#2E9C8E',topic:'Regression & GLMs',q:'Name the three components of a generalised linear model.',a:'A random component (exponential family), a linear predictor Xβ, and a link function g(μ) = Xβ.'},
  {module:'CS1A',sub:'reg-glm',color:'#2E9C8E',topic:'Regression & GLMs',q:'What is the canonical link for a Poisson GLM?',a:'The log link: g(μ) = ln(μ). This ensures the linear predictor can take any real value while μ remains positive.'},
  {module:'CS1A',sub:'reg-glmfit',color:'#2E9C8E',topic:'Regression & GLMs',q:'What is scaled deviance and how is it used to compare nested GLMs?',a:'Scaled deviance = 2(log L_sat − log L_model)/φ. The difference in scaled deviances between two nested models is approximately chi-squared, used as a likelihood ratio test.'},
  // CS1A — Bayesian statistics theory
  {module:'CS1A',sub:'bayes-conj',color:'#2E9C8E',topic:'Bayesian statistics',q:'What is a conjugate prior?',a:'A prior distribution that gives a posterior in the same family, making the Bayesian update tractable.'},
  {module:'CS1A',sub:'bayes-conj',color:'#2E9C8E',topic:'Bayesian statistics',q:"State Bayes' theorem in terms of prior, likelihood, and posterior.",a:'posterior ∝ likelihood × prior, i.e. π(θ|x) ∝ L(θ;x) · π(θ).'},
  {module:'CS1A',sub:'bayes-ci',color:'#2E9C8E',topic:'Bayesian statistics',q:'What is a credible interval?',a:'A Bayesian interval [a,b] such that P(a ≤ θ ≤ b | data) = 0.95 (for 95%). Unlike a frequentist CI, it gives a direct probability statement about the parameter.'},
  {module:'CS1A',sub:'bayes-cred',color:'#2E9C8E',topic:'Bayesian statistics',q:'State the Bühlmann credibility premium formula.',a:"P = Z·X̄ + (1−Z)·μ, where Z = n/(n+k) is the credibility factor, k = σ²/τ² (within-group variance over between-group variance), and μ is the prior mean."},
  // CB1 — Corporate governance
  {module:'CB1',sub:'gov-reg',color:'#6B5DD3',topic:'Corporate governance',q:'What is the primary role of an external auditor?',a:'To give an independent opinion on whether the financial statements give a true and fair view, in accordance with applicable accounting standards.'},
  {module:'CB1',sub:'gov-agency',color:'#6B5DD3',topic:'Corporate governance',q:'What is the agency problem?',a:'Managers (agents) may pursue their own interests rather than maximising shareholder (principal) wealth, due to information asymmetry and misaligned incentives.'},
  {module:'CB1',sub:'gov-ethics',color:'#6B5DD3',topic:'Corporate governance',q:'What does ESG stand for and why is it relevant to corporate governance?',a:'Environmental, Social, and Governance. It measures a company\'s exposure to non-financial risks and ethical conduct, increasingly used by investors and regulators.'},
  {module:'CB1',sub:'gov-finance',color:'#6B5DD3',topic:'Corporate governance',q:'State the shareholder wealth maximisation objective.',a:'Managers should make decisions that maximise the market value of the ordinary shares (market capitalisation), which is the present value of expected future dividends.'},
  // CB1 — How corporates are financed
  {module:'CB1',sub:'fin-capital',color:'#6B5DD3',topic:'Corporate finance',q:'Write the formula for the Weighted Average Cost of Capital.',a:'WACC = (E/V)·re + (D/V)·rd·(1 − T).'},
  {module:'CB1',sub:'fin-capital',color:'#6B5DD3',topic:'Corporate finance',q:"State Modigliani-Miller Proposition I (with taxes).",a:'The value of a geared firm equals the value of an equivalent ungeared firm plus the present value of the tax shield: V_L = V_U + T·D.'},
  {module:'CB1',sub:'fin-deriv',color:'#6B5DD3',topic:'Corporate finance',q:'What is the difference between a put option and a call option?',a:'A call gives the right (not obligation) to buy an asset at the strike price; a put gives the right to sell. Both require paying a premium upfront.'},
  {module:'CB1',sub:'fin-tax',color:'#6B5DD3',topic:'Corporate finance',q:'What is the tax shield on debt?',a:'The tax saving arising because interest payments are tax-deductible: Tax shield = T × r_D × D per year, or PV = T × D for permanent debt.'},
  {module:'CB1',sub:'fin-short',color:'#6B5DD3',topic:'Corporate finance',q:'What is invoice discounting?',a:'A form of short-term finance where a lender advances cash against unpaid invoices; the company retains credit control, and the arrangement is usually confidential.'},
  {module:'CB1',sub:'fin-struct',color:'#6B5DD3',topic:'Corporate finance',q:'Distinguish between loan capital and share capital.',a:'Loan capital (debt) carries a fixed obligation to pay interest and repay principal; holders rank ahead of shareholders on insolvency. Share capital carries no fixed payment; holders receive residual returns.'},
  // CB1 — Evaluating projects
  {module:'CB1',sub:'proj-coc',color:'#6B5DD3',topic:'Evaluating projects',q:'Write the CAPM formula for the required return on equity.',a:'E(r_i) = r_f + β_i (E(r_m) − r_f), where r_f is the risk-free rate and (E(r_m) − r_f) is the market risk premium.'},
  {module:'CB1',sub:'proj-npv',color:'#6B5DD3',topic:'Evaluating projects',q:'Why is NPV preferred over IRR for choosing between mutually exclusive projects?',a:'IRR can rank projects incorrectly when they differ in scale or timing of cashflows, and may give multiple values if cashflows change sign more than once. NPV measures absolute value added.'},
  {module:'CB1',sub:'proj-risk',color:'#6B5DD3',topic:'Evaluating projects',q:'What is a sensitivity analysis in project appraisal?',a:'It measures how much a key input variable (e.g. sales volume, discount rate) must change for the NPV to become zero, indicating the margin of safety.'},
  // CB1 — Accounts
  {module:'CB1',sub:'acc-concepts',color:'#6B5DD3',topic:'Interpreting accounts',q:'State the accruals concept.',a:'Revenue and expenses are recognised when earned or incurred, not when cash is received or paid, so the income statement reflects economic activity for the period.'},
  {module:'CB1',sub:'acc-stmts',color:'#6B5DD3',topic:'Interpreting accounts',q:'What does the statement of cash flows show that the income statement does not?',a:'Actual cash movements — operating, investing and financing — revealing whether the company generates sufficient cash to fund operations and growth, independent of accrual accounting choices.'},
  {module:'CB1',sub:'acc-construct',color:'#6B5DD3',topic:'Interpreting accounts',q:'Compare FIFO and AVCO for inventory valuation in a rising price environment.',a:'FIFO matches older (cheaper) costs to cost of sales, giving higher profit and higher closing stock. AVCO averages costs, giving an intermediate result. FIFO better reflects current stock value on the balance sheet.'},
  {module:'CB1',sub:'acc-ratios',color:'#6B5DD3',topic:'Interpreting accounts',q:"What does a company's gearing measure?",a:'The proportion of debt in its capital structure — debt relative to equity (or to total capital).'},
  {module:'CB1',sub:'acc-proflik',color:'#6B5DD3',topic:'Interpreting accounts',q:'Define Return on Capital Employed (ROCE).',a:'ROCE = EBIT / (Total assets − Current liabilities). It measures how efficiently the company uses its long-term capital to generate operating profit.'},
  {module:'CB1',sub:'acc-consol',color:'#6B5DD3',topic:'Interpreting accounts',q:'When is goodwill recognised in group accounts?',a:'On acquisition, goodwill = consideration paid − fair value of net assets acquired. It appears as an intangible asset and is tested annually for impairment rather than amortised.'},
];

// ── EXTRA CARDS ──────────────────────────────────────────────────────────────
const EXTRA_CARDS = [
  // CM1A — cashflows & annuities
  {module:'CM1A',sub:'int-cashflow',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is an annuity-due and how does its present value differ from an annuity-immediate?',a:'An annuity-due pays at the start of each period; an annuity-immediate pays at the end. ä_{n|} = (1+i)·a_{n|}, i.e. each payment is received one period earlier, so the annuity-due is worth a factor (1+i) more.'},
  {module:'CM1A',sub:'int-cashflow',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is a perpetuity and what is its present value?',a:'A perpetuity pays £1 per year forever. PV = 1/i (annuity-immediate) or 1/d (annuity-due), where d = i/(1+i) is the rate of discount.'},
  {module:'CM1A',sub:'int-pv',color:'#3D6FD1',topic:'Theory of interest rates',q:'How do you find the accumulated value at time T of a discrete cashflow c_t paid at time t?',a:'AV = Σ c_t · (1+i)^{T−t}. Each cashflow is accumulated forward to time T at the rate of interest.'},
  {module:'CM1A',sub:'int-ann',color:'#3D6FD1',topic:'Theory of interest rates',q:'Write the accumulation factor s_{n|} for an annuity-immediate and express it in terms of a_{n|}.',a:'s_{n|} = ((1+i)^n − 1)/i = (1+i)^n · a_{n|}. It is the value at time n of £1 paid at the end of each year for n years.'},
  {module:'CM1A',sub:'int-ann',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is a continuous annuity ā_{n|} and how is it computed?',a:'ā_{n|} = ∫₀ⁿ e^{−δt} dt = (1 − e^{−δn})/δ. It is the PV of £1 per year paid continuously for n years.'},
  {module:'CM1A',sub:'int-duration',color:'#3D6FD1',topic:'Theory of interest rates',q:'Define Macaulay duration.',a:'Macaulay duration D = (Σ t · PV(c_t)) / (Σ PV(c_t)) — the weighted average time to receipt of cashflows, with PV weights. It measures price sensitivity to yield changes.'},
  {module:'CM1A',sub:'int-duration',color:'#3D6FD1',topic:'Theory of interest rates',q:'How is modified duration related to Macaulay duration?',a:"Modified duration D* = D/(1+i). The percentage change in price for a small change in yield is approximately −D*·Δi, i.e. dP/P ≈ −D*·di."},
  // CM1A — loans & bonds
  {module:'CM1A',sub:'eqv-loan',color:'#3D6FD1',topic:'Equation of value',q:'What is the outstanding loan balance immediately after the k-th instalment under a level annuity loan?',a:'Prospective: PV of remaining instalments, L_k = X · a_{n−k|i}. Retrospective: L_k = L·(1+i)^k − X·s_{k|i}.'},
  {module:'CM1A',sub:'eqv-loan',color:'#3D6FD1',topic:'Equation of value',q:'Define the Annual Percentage Rate (APR) of a loan.',a:'The APR is the effective annual interest rate i at which the present value of all repayments equals the amount borrowed — it is the IRR from the lender\'s perspective, expressed as a percentage per annum.'},
  {module:'CM1A',sub:'eqv-bonds',color:'#3D6FD1',topic:'Equation of value',q:'What happens to the price of a fixed-coupon bond when market yields rise?',a:'The price falls. Bond prices and yields move inversely: a higher discount rate reduces the PV of future coupon and redemption cashflows, so the bond is worth less.'},
  {module:'CM1A',sub:'eqv-bonds',color:'#3D6FD1',topic:'Equation of value',q:'What is the par yield of a bond?',a:'The coupon rate at which the bond is priced exactly at par (P = C). At the par yield, coupon income exactly compensates the investor for the time value of money, so no capital gain or loss is expected.'},
  {module:'CM1A',sub:'eqv-shares',color:'#3D6FD1',topic:'Equation of value',q:'Under the dividend discount model with no dividend growth, what is the share price?',a:'P = D/k, where D is the constant annual dividend and k is the required return — equivalent to a perpetuity.'},
  {module:'CM1A',sub:'eqv-proj',color:'#3D6FD1',topic:'Equation of value',q:'What is the payback period of a project and what is its main weakness?',a:'The time until cumulative cashflows turn positive (the initial investment is recovered). Its main weakness is that it ignores cashflows after the payback date and does not account for the time value of money.'},
  // CM1B — life tables
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What is the curtate future lifetime K_x?',a:'K_x = ⌊T_x⌋ is the integer part of the complete future lifetime T_x — the number of complete years lived after age x. K_x takes values 0, 1, 2, … with P(K_x = k) = k|q_x.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'State the relationship between q_x, p_x, and μ_x under the assumption of a constant force of mortality.',a:'Under constant μ over [x, x+1]: q_x = 1 − e^{−μ} and p_x = e^{−μ}.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What is the UDD (Uniform Distribution of Deaths) assumption and what does it imply?',a:'UDD assumes deaths are spread uniformly within each year of age: t·q_x = t · q_x for 0 ≤ t ≤ 1. It implies the force of mortality increases within the year and deaths occur on average at mid-year.'},
  {module:'CM1B',sub:'dec-multi',color:'#3D6FD1',topic:'Decrement models',q:'Define joint-life and last-survivor annuities for two lives aged x and y.',a:'Joint-life annuity ā_{xy} pays while both are alive (stops on first death). Last-survivor annuity ā_{x̄ȳ} pays while at least one is alive. They satisfy ā_{xy} + ā_{x̄ȳ} = ā_x + ā_y.'},
  // CM1B — assurance EPVs
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is the EPV of a whole-life immediate annuity of £1 p.a. for a life aged x, and how is it related to A_x?',a:'ā_x = (1 − A_x)/δ (continuous) or a_x = (1 − A_x)/i (discrete, end-of-year). These follow from the identity that the benefit can be represented as a perpetuity minus the assurance.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is a term assurance A_{x:n|}^1 and how does it differ from A_{x:n|}?',a:'A_{x:n|}^1 (term assurance) pays only on death within n years; A_{x:n|} (endowment assurance) pays on death within n years OR at maturity. A_{x:n|} = A_{x:n|}^1 + A_{x:n|}^{  1} where A_{x:n|}^{  1} = v^n · n·p_x is the pure endowment.'},
  // CM1B — reserving extras
  {module:'CM1B',sub:'res-equiv',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the prospective reserve and the retrospective reserve.',a:'Prospective: EPV of future benefits & expenses minus EPV of future premiums (forward-looking). Retrospective: accumulated value of past premiums minus accumulated cost of past benefits & expenses (backward-looking). Both equal the same value when computed on the premium basis.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'What is the purpose of profit testing a life insurance contract?',a:'To project the expected profit emerging each year, allowing the insurer to: (1) set premiums, (2) check adequacy of reserves, (3) assess profitability and return on capital, (4) identify years of expected loss that may require non-unit reserves.'},
  {module:'CM1B',sub:'dec-mdt',color:'#3D6FD1',topic:'Decrement models',q:'Give an example of a multiple decrement model in pensions.',a:'A pension scheme member can leave by: death, ill-health retirement, age retirement, or withdrawal (resignation). Each has its own decrement rate, and the table combines all decrements to give probabilities of remaining active year by year.'},
  // CS1A extras — data & distributions
  {module:'CS1A',sub:'data-aims',color:'#2E9C8E',topic:'Data analysis',q:'What is meant by reproducibility in data analysis?',a:'That another analyst can re-run exactly the same steps on the same data and obtain identical results. It requires documenting code, data sources, and software versions — facilitated by tools like R Markdown or version control.'},
  {module:'CS1A',sub:'data-explore',color:'#2E9C8E',topic:'Data analysis',q:'What does a boxplot display?',a:'The five-number summary: minimum, lower quartile (Q1), median (Q2), upper quartile (Q3), maximum. Whiskers extend to the most extreme non-outlier values; points beyond 1.5×IQR from the box are plotted individually as potential outliers.'},
  {module:'CS1A',sub:'data-pca',color:'#2E9C8E',topic:'Data analysis',q:'What are the principal components in PCA?',a:'Linear combinations of the original variables that are mutually uncorrelated and capture decreasing amounts of variance. The first PC has maximum variance; each subsequent PC is orthogonal to all previous ones.'},
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'State the mean and variance of a Normal(μ, σ²) distribution.',a:'Mean = μ, Variance = σ². The normal is symmetric about μ; ≈68% of values lie within ±1σ, ≈95% within ±2σ.'},
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'What is the lognormal distribution and when is it used in actuarial work?',a:'If ln(X) ~ N(μ, σ²) then X is lognormal. Used for claim severities, asset prices and mortality improvements — all positive and right-skewed. Mean = e^{μ+σ²/2}, Variance = e^{2μ+σ²}(e^{σ²}−1).'},
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'What is the Pareto distribution and why is it used for insurance claims?',a:'X ~ Pareto(α, λ) has a heavy right tail: P(X>x) = (λ/(λ+x))^α. Used when large claims are much more likely than under a normal model — models claim severity for catastrophe or liability lines.'},
  {module:'CS1A',sub:'rv-joint',color:'#2E9C8E',topic:'Random variables',q:'What is the difference between independence and zero correlation?',a:'Independence implies zero correlation, but zero correlation does NOT imply independence (except for jointly normal random variables). Two variables can have Cov(X,Y)=0 yet be dependent (e.g. Y=X²).'},
  {module:'CS1A',sub:'rv-sampling',color:'#2E9C8E',topic:'Random variables',q:'What is the t-distribution and when is it used instead of the normal?',a:'The t-distribution with ν degrees of freedom has heavier tails than the normal. It is used for inference on a normal mean when σ² is unknown: (X̄−μ)/(S/√n) ~ t_{n−1}. As ν→∞ it converges to N(0,1).'},
  {module:'CS1A',sub:'rv-sampling',color:'#2E9C8E',topic:'Random variables',q:'Define the F-distribution and state one use.',a:'If U ~ χ²(m) and V ~ χ²(n) independently, then F = (U/m)/(V/n) ~ F(m,n). Used to compare two sample variances, and in ANOVA to test whether group means differ.'},
  // CS1A — inference extras
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'What is the bootstrap method of estimation?',a:'Resample the data with replacement B times, compute the statistic of interest on each resample, and use the resulting empirical distribution to estimate standard errors or confidence intervals — useful when no closed-form formula exists.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'State the chi-squared goodness-of-fit test statistic and its null distribution.',a:'X² = Σ (O_i − E_i)²/E_i, summed over k cells. Under H₀ (specified distribution), X² is approximately χ²(k−1−p), where p is the number of parameters estimated from the data.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'What is a Type I and Type II error in hypothesis testing?',a:'Type I: rejecting H₀ when it is true (false positive); probability = significance level α. Type II: failing to reject H₀ when it is false (false negative); probability = β. Power = 1 − β.'},
  {module:'CS1A',sub:'inf-ci',color:'#2E9C8E',topic:'Statistical inference',q:'How do you construct a 95% CI for a Poisson rate λ from n observations with total count x?',a:'Use x ~ Poisson(nλ). Approximate CI: x/n ± 1.96√(x)/n. Exact CI uses chi-squared quantiles: [χ²(2x, 0.025)/(2n), χ²(2x+2, 0.975)/(2n)].'},
  // CS1A — regression theory extras
  {module:'CS1A',sub:'reg-lm',color:'#2E9C8E',topic:'Regression',q:'What does R² measure in linear regression and what is its main limitation?',a:'R² = 1 − SS_res/SS_tot is the proportion of variance in Y explained by the model. Limitation: it always increases when predictors are added, even useless ones — use adjusted R² or AIC/BIC to penalise for model complexity.'},
  {module:'CS1A',sub:'reg-lm',color:'#2E9C8E',topic:'Regression',q:'State the four assumptions of the classical linear regression model.',a:'(1) Linearity: E[Y|X] = Xβ. (2) Homoscedasticity: Var(ε_i) = σ² (constant). (3) Independence: errors are uncorrelated. (4) Normality: ε ~ N(0, σ²I). Violations are diagnosed via residual plots.'},
  {module:'CS1A',sub:'reg-diag',color:'#2E9C8E',topic:'Regression',q:'What is leverage in regression and why does high leverage matter?',a:"Leverage h_{ii} = (H)_{ii} (the i-th diagonal of the hat matrix H = X(X'X)^{-1}X') measures how far observation i's predictors are from the mean. High leverage means x_i has potential to pull the regression line, so even a moderate residual can be influential."},
  {module:'CS1A',sub:'reg-glm',color:'#2E9C8E',topic:'Regression & GLMs',q:'What is the canonical link for a Gamma GLM?',a:'The reciprocal (inverse) link: g(μ) = 1/μ, giving the linear predictor as 1/μ = Xβ. The log link is often used instead because it ensures μ > 0 and is easier to interpret.'},
  {module:'CS1A',sub:'reg-glmfit',color:'#2E9C8E',topic:'Regression & GLMs',q:'What are Pearson residuals in a GLM?',a:'r_P = (y − μ̂)/√V(μ̂), standardised by the square root of the variance function. They should be approximately N(0,1) if the model is correct; patterns indicate model misspecification.'},
  // CS1A — Bayesian theory extras
  {module:'CS1A',sub:'bayes-conj',color:'#2E9C8E',topic:'Bayesian statistics',q:'If X|θ ~ Binomial(n,θ) and θ ~ Beta(α,β), what is the posterior?',a:'θ|x ~ Beta(α+x, β+n−x). The Beta-Binomial is the classic conjugate pair. Posterior mean = (α+x)/(α+β+n), a weighted average of prior mean α/(α+β) and sample proportion x/n.'},
  {module:'CS1A',sub:'bayes-ci',color:'#2E9C8E',topic:'Bayesian statistics',q:'What is the highest posterior density (HPD) region?',a:'The shortest credible interval such that every point inside has higher posterior density than every point outside. For symmetric unimodal posteriors it equals the equal-tailed interval; for skewed posteriors it differs.'},
  {module:'CS1A',sub:'bayes-cred',color:'#2E9C8E',topic:'Bayesian statistics',q:'In credibility theory, what does a credibility factor Z close to 1 mean?',a:'Z close to 1 means the observed data are given high weight relative to the prior mean — this occurs when n is large (much data) or when within-risk variance is small relative to between-risk variance (risk is homogeneous).'},
  // CB1 — governance extras
  {module:'CB1',sub:'gov-reg',color:'#6B5DD3',topic:'Corporate governance',q:'What is the role of the audit committee within corporate governance?',a:'An independent sub-committee of the board (mainly non-executive directors) that oversees financial reporting, internal controls, the internal audit function, and the relationship with external auditors.'},
  {module:'CB1',sub:'gov-ethics',color:'#6B5DD3',topic:'Corporate governance',q:'What is corporate social responsibility (CSR)?',a:'A company\'s voluntary commitment to manage its social, environmental and ethical impact beyond legal requirements — including community engagement, environmental stewardship and ethical supply chains.'},
  {module:'CB1',sub:'gov-finance',color:'#6B5DD3',topic:'Corporate governance',q:'List four stakeholders of a company other than shareholders.',a:'Employees (jobs, pay), creditors (interest/repayment), customers (product quality), suppliers (trade terms), government (taxes, regulation), local communities (employment, environment).'},
  // CB1 — financing extras
  {module:'CB1',sub:'fin-medium',color:'#6B5DD3',topic:'Corporate finance',q:'What is the difference between hire purchase and a finance lease?',a:'Hire purchase: the asset is eventually owned by the lessee after all instalments are paid. Finance lease: ownership stays with the lessor, but substantially all risks and rewards transfer to the lessee; the asset and liability appear on the lessee\'s balance sheet.'},
  {module:'CB1',sub:'fin-alt',color:'#6B5DD3',topic:'Corporate finance',q:'What is peer-to-peer (P2P) lending?',a:'An online platform that directly matches borrowers with individual lenders, bypassing banks. Lenders earn interest; borrowers get funds faster, often at competitive rates. Risk: no deposit protection; platform default risk.'},
  {module:'CB1',sub:'fin-instr',color:'#6B5DD3',topic:'Corporate finance',q:'What is a convertible bond?',a:'A bond that gives the holder the right to convert into ordinary shares at a pre-set conversion price. It offers downside protection (bond floor) with upside equity participation. Issued at a lower coupon than plain debt.'},
  {module:'CB1',sub:'fin-instr',color:'#6B5DD3',topic:'Corporate finance',q:'What is an asset-backed security (ABS)?',a:'A security whose cashflows are backed by a pool of underlying assets (e.g. mortgages, credit card receivables). The originator sells the assets to a special purpose vehicle (SPV) which issues the ABS, transferring credit risk to investors.'},
  {module:'CB1',sub:'fin-deriv',color:'#6B5DD3',topic:'Corporate finance',q:'What is the difference between exchange-traded and OTC derivatives?',a:'Exchange-traded: standardised contracts on a regulated exchange with a central counterparty (clearing house) eliminating counterparty risk. OTC: customised bilateral contracts — more flexible but carry counterparty credit risk and less transparency.'},
  {module:'CB1',sub:'fin-issue',color:'#6B5DD3',topic:'Corporate finance',q:'What is an IPO and what are the main methods of flotation?',a:'Initial Public Offering — first sale of shares to the public. Methods: (1) Offer for sale (fixed price or book-built), (2) Placing (shares sold to institutional investors), (3) Introduction (existing shares admitted, no new money raised), (4) Public offer.'},
  {module:'CB1',sub:'fin-growth',color:'#6B5DD3',topic:'Corporate finance',q:'What is the difference between a merger and an acquisition?',a:'Merger: two companies combine to form a new entity (roughly equal partners). Acquisition: one company (the acquirer) purchases a controlling interest in another (the target), which may retain its legal identity. Most "mergers" are effectively acquisitions.'},
  {module:'CB1',sub:'fin-capital',color:'#6B5DD3',topic:'Corporate finance',q:'State the pecking order theory of capital structure.',a:'Firms prefer internally generated funds first, then debt, then equity as a last resort. This avoids signalling problems: issuing equity signals managers think the stock is overvalued, depressing the price. Debt has a smaller signalling effect.'},
  // CB1 — project appraisal extras
  {module:'CB1',sub:'proj-cashflow',color:'#6B5DD3',topic:'Evaluating projects',q:'Why are sunk costs excluded from project appraisal?',a:'Sunk costs have already been incurred and cannot be recovered regardless of the decision. Only incremental (relevant) future cashflows that differ between the options should be included in NPV analysis.'},
  {module:'CB1',sub:'proj-risk',color:'#6B5DD3',topic:'Evaluating projects',q:'What is the certainty equivalent approach to risk in project appraisal?',a:'Replace risky cashflows with their certainty equivalents (smaller, risk-free amounts the decision-maker finds equally attractive) and discount at the risk-free rate. This separates risk adjustment from time preference, unlike the risk-adjusted discount rate method.'},
  {module:'CB1',sub:'proj-ident',color:'#6B5DD3',topic:'Evaluating projects',q:'What is a probability-impact matrix used for in risk assessment?',a:'It plots identified risks on a grid of probability (low to high) vs impact (low to high). Risks in the high-probability / high-impact quadrant are prioritised for mitigation. It is qualitative and helps communicate risk exposure to stakeholders.'},
  // CB1 — accounts extras
  {module:'CB1',sub:'acc-purpose',color:'#6B5DD3',topic:'Interpreting accounts',q:'What is the TCFD framework?',a:'Task Force on Climate-related Financial Disclosures — recommends companies disclose how climate risks affect governance, strategy, risk management, and key metrics/targets. Increasingly mandatory for listed companies.'},
  {module:'CB1',sub:'acc-construct',color:'#6B5DD3',topic:'Interpreting accounts',q:'What is goodwill and how is it recorded on the balance sheet?',a:'Goodwill = price paid for a business above the fair value of its identifiable net assets. It reflects intangibles like brand and customer relationships. Under IFRS it is not amortised but tested annually for impairment; under US GAAP historically amortised.'},
  {module:'CB1',sub:'acc-insbank',color:'#6B5DD3',topic:'Interpreting accounts',q:'What are technical provisions in an insurance company\'s balance sheet?',a:'Liabilities representing the insurer\'s estimate of future claims and expenses for policies in force. They include the claims reserve (IBNR + outstanding claims) and unearned premium reserve (for general insurance) or policy reserves (for life insurance).'},
  {module:'CB1',sub:'acc-consol',color:'#6B5DD3',topic:'Interpreting accounts',q:'How is an associate company treated in group accounts under IFRS?',a:'An associate (20–50% ownership, significant influence) is accounted for using the equity method: the investment appears as a single line on the balance sheet at cost plus share of post-acquisition profits; the income statement shows the group\'s share of the associate\'s profit.'},
  {module:'CB1',sub:'acc-proflik',color:'#6B5DD3',topic:'Interpreting accounts',q:'What does the current ratio measure and what level is generally considered healthy?',a:'Current ratio = Current assets / Current liabilities. It measures short-term liquidity. A ratio around 1.5–2 is often cited as comfortable, though industry norms vary. Below 1 suggests potential difficulty meeting short-term obligations.'},
  {module:'CB1',sub:'acc-proflik',color:'#6B5DD3',topic:'Interpreting accounts',q:'What is EBITDA and why do analysts use it?',a:'Earnings Before Interest, Tax, Depreciation and Amortisation. It approximates operating cash generation, removing the effect of financing (interest), tax jurisdiction, and non-cash accounting charges — useful for comparing operating performance across companies or capital structures.'},

  // ── CB1 RISK & GOVERNANCE EXTRAS ─────────────────────────────────────────
  {module:'CB1',sub:'proj-risk',color:'#6B5DD3',topic:'Evaluating projects',q:'What is a Monte Carlo simulation in project appraisal?',a:'A method that runs thousands of NPV calculations, each time sampling input variables (e.g. sales, costs, discount rate) from their probability distributions. The result is a distribution of possible NPVs, showing the probability of a positive outcome rather than a single point estimate.'},
  {module:'CB1',sub:'proj-risk',color:'#6B5DD3',topic:'Evaluating projects',q:'What is scenario analysis and how does it differ from sensitivity analysis?',a:'Sensitivity analysis changes one variable at a time to find the break-even point. Scenario analysis changes multiple variables simultaneously (e.g. pessimistic, base, optimistic) to capture correlated risks, giving a more realistic picture of potential outcomes under coherent economic assumptions.'},
  {module:'CB1',sub:'proj-ident',color:'#6B5DD3',topic:'Evaluating projects',q:'List the main categories of risk faced by a company.',a:'Business risk (market, operational, strategic), financial risk (credit, liquidity, interest rate, FX), regulatory/legal risk, reputational risk, ESG/climate risk. Business risk affects all firms; financial risk depends on the capital structure and funding mix.'},
  {module:'CB1',sub:'proj-ident',color:'#6B5DD3',topic:'Evaluating projects',q:'What is the difference between systematic and unsystematic risk?',a:'Systematic (market) risk cannot be diversified away — it is driven by macroeconomic factors affecting all assets (e.g. GDP, interest rates). Unsystematic (specific) risk is company or industry-specific and can be eliminated by diversification. CAPM only prices systematic risk (β).'},
  {module:'CB1',sub:'gov-reg',color:'#6B5DD3',topic:'Corporate governance',q:'What is the UK Corporate Governance Code?',a:'A set of principles and provisions for UK listed companies covering board leadership, effectiveness, accountability, remuneration and stakeholder relations. Listed companies must comply or explain deviations. Published by the FRC and revised periodically.'},
  {module:'CB1',sub:'gov-reg',color:'#6B5DD3',topic:'Corporate governance',q:'What are the duties of company directors under UK company law?',a:'Key duties under CA 2006: (1) act in good faith in the interests of the company; (2) promote success for shareholders as a whole; (3) exercise independent judgement; (4) avoid conflicts of interest; (5) not accept third-party benefits; (6) declare interest in transactions.'},
  {module:'CB1',sub:'gov-agency',color:'#6B5DD3',topic:'Corporate governance',q:'What mechanisms can reduce the agency problem between managers and shareholders?',a:'(1) Performance-related pay and share options (align incentives); (2) non-executive directors and audit committee (monitoring); (3) shareholder voting rights and AGM; (4) executive contracts with clawback provisions; (5) transparent disclosure requirements.'},
  {module:'CB1',sub:'fin-medium',color:'#6B5DD3',topic:'Corporate finance',q:'What is the difference between a bank overdraft and a term loan?',a:'An overdraft is a short-term revolving facility — you borrow and repay flexibly up to a limit, paying interest only on the daily balance. A term loan has a fixed amount, fixed repayment schedule and typically a longer maturity; it is less flexible but provides certainty of funding.'},
  {module:'CB1',sub:'fin-alt',color:'#6B5DD3',topic:'Corporate finance',q:'What is direct project financing as a form of alternative finance?',a:"Funding raised for a specific project (often infrastructure) where lenders are repaid mainly from that project's own cashflows, with the project's assets as security, rather than from the sponsor's general balance sheet. It sits outside the regular banking system and ring-fences project risk in a separate vehicle."},
  {module:'CB1',sub:'fin-struct',color:'#6B5DD3',topic:'Corporate finance',q:'What are preference shares and how do they differ from ordinary shares?',a:'Preference shares carry a fixed dividend paid before ordinary shareholders, and have priority on liquidation. They typically have no voting rights. Cumulative preference shares accumulate unpaid dividends; participating preference shares may share in residual profits. They are a hybrid between debt and equity.'},
  {module:'CB1',sub:'fin-tax',color:'#6B5DD3',topic:'Corporate finance',q:'What is the difference between corporation tax and capital gains tax for a company?',a:'Corporation tax applies to trading profits and is the main tax on company profits. A company\'s chargeable gains (from selling assets) are also taxed at the corporation tax rate. Capital gains tax (CGT) applies to individuals and trusts disposing of assets, not companies.'},
  {module:'CB1',sub:'acc-purpose',color:'#6B5DD3',topic:'Interpreting accounts',q:'Who are the primary users of financial statements and what do they need from them?',a:'Shareholders (investment decisions, stewardship), lenders/creditors (credit risk, repayment ability), employees (job security, pay), customers (going concern), government (tax, regulation). Each group uses different ratios and focuses on different statements — e.g. creditors focus on cash flow and gearing.'},
  {module:'CB1',sub:'acc-ratios',color:'#6B5DD3',topic:'Interpreting accounts',q:'Calculate and interpret the interest coverage ratio.',a:'Interest cover = EBIT / Interest expense. It measures how many times the company can cover its interest payments from operating profit. A ratio below 2 is often considered risky; below 1 means the company cannot cover interest from operations. Used by creditors to assess default risk.'},

  // ── CM1A EXTRAS — interest theory edge cases ──────────────────────────────
  {module:'CM1A',sub:'int-force',color:'#3D6FD1',topic:'Theory of interest rates',q:'If the force of interest varies with time as δ(t), what is the accumulation factor from time 0 to t?',a:'A(0,t) = exp(∫₀ᵗ δ(s) ds). For a constant force δ, this reduces to e^{δt}.'},
  {module:'CM1A',sub:'int-rates',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is the effective rate of discount d and how is it related to i?',a:'d = i/(1+i) = 1 − v = iv, where v = 1/(1+i). It is the amount of interest paid at the beginning of the period per unit repaid at the end.'},
  {module:'CM1A',sub:'int-cashflow',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is a deferred annuity?',a:'An annuity where payments start after a deferral period of m years. PV = v^m · a_{n|i}. The m-year deferral factor v^m discounts the annuity back to time 0.'},
  {module:'CM1A',sub:'eqv-proj',color:'#3D6FD1',topic:'Equation of value',q:'What is the net present value (NPV) of a project?',a:'NPV = PV(inflows) − PV(outflows), discounted at the required rate of return. If NPV > 0, the project adds value and should be accepted. It directly measures the wealth created for shareholders.'},
  {module:'CM1A',sub:'eqv-basic',color:'#3D6FD1',topic:'Equation of value',q:'What is a loan schedule (amortisation table)?',a:'A table showing for each period: opening balance, interest charged, capital repaid, and closing balance. It breaks down each instalment into its interest and capital components, with interest declining as the outstanding balance falls.'},

  // ── CM1B EXTRAS — mortality and Markov ───────────────────────────────────
  {module:'CM1B',sub:'dec-markov',color:'#3D6FD1',topic:'Decrement models',q:'What is the Chapman-Kolmogorov equation in a continuous Markov model?',a:'ₛ₊ₜp_{ij} = Σₖ ₛp_{ik} · ₜp_{kj}. The probability of moving from i to j in time s+t equals the probability of passing through any intermediate state k after time s and then reaching j in the remaining time t.'},
  {module:'CM1B',sub:'res-grossprem',color:'#3D6FD1',topic:'Pricing & reserving',q:"What is an expense loading in a life insurance premium?",a:"The addition to the net premium to cover expenses: initial (commission, setup), renewal (admin, reassurance), and per-policy charges. The gross premium = net premium + expense loading. Expense loadings are typically expressed as a percentage of premium or sum assured plus a fixed per-policy amount."},
  {module:'CM1B',sub:'res-reserve',color:'#3D6FD1',topic:'Pricing & reserving',q:"What is a negative reserve and when does it arise?",a:"A negative reserve arises when EPV(future premiums) > EPV(future benefits + expenses) — typically in early policy years when large initial expenses have been paid. Regulators usually require negative reserves to be set to zero (zeroed), with the insurer treating this as a capital cost."},

  // ── CS1A EXTRAS — inference and GLMs ──────────────────────────────────────
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'What is the likelihood ratio test and what distribution is its statistic approximately?',a:'For nested models, LRT statistic = 2(ln L_full − ln L_restricted) ~ χ²(df) under H₀, where df = difference in number of parameters. Used widely for GLM comparison, equivalent to the deviance difference test.'},
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'State the large-sample distribution of the MLE θ̂.',a:'θ̂ is approximately N(θ, 1/I(θ)) for large n, where I(θ) is the Fisher information. This justifies Wald confidence intervals: θ̂ ± z_{α/2}/√I(θ̂).'},
  {module:'CS1A',sub:'reg-glm',color:'#2E9C8E',topic:'Regression & GLMs',q:'What distributions belong to the exponential family relevant to CS1 GLMs?',a:'Normal (continuous response, identity link), Poisson (count data, log link), Binomial (proportions, logit link), Gamma (positive continuous, log or reciprocal link), Inverse Gaussian. Each has a specific variance function V(μ) that determines the mean-variance relationship.'},
  {module:'CS1A',sub:'reg-lm',color:'#2E9C8E',topic:'Regression',q:'What is multicollinearity and how does it affect regression estimates?',a:'Multicollinearity exists when predictors are highly correlated. It inflates standard errors, making coefficients unstable and hard to interpret, though predictions remain unbiased. Detected via Variance Inflation Factor (VIF > 10 is problematic). Remedies: remove correlated predictors, ridge regression, or PCA.'},
  {module:'CS1A',sub:'bayes-cred',color:'#2E9C8E',topic:'Bayesian statistics',q:'What is the EBCT (Empirical Bayes Credibility Theory) Model 1?',a:'Bühlmann credibility: each risk has its own θ. m(θ) = E[X|θ], s²(θ) = Var[X|θ]. Structural parameters: μ = E[m(θ)], σ² = E[s²(θ)], τ² = Var[m(θ)]. Credibility factor Z = n/(n+k), k = σ²/τ². The credibility premium is a weighted average of the risk\'s own mean and the portfolio mean.'},

  // ── CS1B EXTRAS — R and Bayesian practice ────────────────────────────────
  {module:'CS1B',sub:'cs1b-data-explore',color:'#2E9C8E',topic:'R: Data exploration',q:'How do you compute summary statistics and correlation in R?',a:'summary(df) gives min, Q1, median, mean, Q3, max for each column. cor(df) gives the Pearson correlation matrix. For Spearman: cor(df, method="spearman"). Use pairs(df) for a scatterplot matrix of all variable pairs.'},
  {module:'CS1B',sub:'cs1b-reg-lm',color:'#2E9C8E',topic:'R: Regression',q:'How do you add an interaction term in lm() in R?',a:'Use * for main effects + interaction: lm(y ~ x1 * x2) expands to y ~ x1 + x2 + x1:x2. Use : for interaction only: lm(y ~ x1 + x2 + x1:x2). Interaction means the effect of x1 differs depending on the value of x2.'},
  {module:'CS1B',sub:'cs1b-bayes-conj',color:'#2E9C8E',topic:'R: Bayesian',q:'How do you compute the posterior mean and credible interval for a Gamma-Poisson conjugate model in R?',a:'If prior θ ~ Gamma(α, β) and data give total count Σx over n periods, posterior is Gamma(α+Σx, β+n). Posterior mean: (α+sum(x))/(β+n). 95% CI: qgamma(c(0.025,0.975), shape=α+sum(x), rate=β+n).'},

  // ── CM1B RESERVES & PROFIT TESTING EXTRAS ────────────────────────────────
  {module:'CM1B',sub:'res-equiv',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the net premium reserve.',a:'The reserve calculated using the net premium (with no expense loading) and the premium basis mortality/interest. It equals EPV(future benefits) − P_net × a_{x+t:n−t|}, evaluated at the valuation date. It is generally larger than the gross premium reserve because P_net > P_gross (no expense loading cuts the premium).'},
  {module:'CM1B',sub:'res-grossprem',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the gross premium reserve.',a:'The reserve calculated using the gross premium (including expense loading) and the valuation basis: EPV(future benefits + future expenses) − P_gross × EPV(future premium annuity). Because the gross premium exceeds the net premium, the gross premium reserve is smaller and can be negative in early years.'},
  {module:'CM1B',sub:'res-equiv',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the prospective reserve.',a:'The prospective reserve is the expected present value of future benefits and expenses minus the expected present value of future premiums, all calculated at the valuation date using the valuation basis. It is "forward-looking": what does the insurer still owe, net of what the policyholder will still pay?'},
  {module:'CM1B',sub:'res-reserve',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the retrospective reserve.',a:'The retrospective reserve is the accumulated value of past premium income less past benefits and expenses, brought forward to the valuation date using the premium basis. It answers: how much has been banked on behalf of this policy so far? It equals the prospective reserve when both are computed on the same basis.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'What is the asset share of a policy?',a:'The asset share AS_t is the actual accumulated fund per policy in force at time t, built from real premiums received, actual investment returns, and actual claims and expenses paid. It represents what the insurer actually holds, as opposed to the theoretical reserve. Comparing AS_t to the reserve reveals under- or over-funding.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'Write the asset share recursion.',a:'AS_t = (AS_{t−1} + P − e_t)(1+i^A) − (S+E_t)·q^A_{x+t−1}, where i^A = actual investment return, e_t = renewal expenses, S = death benefit, E_t = death claim expenses, q^A = actual mortality rate. Initial asset share is −(initial expense) since commission is paid upfront before any premium arrives.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'What is profit testing per unit sum assured?',a:'Divide every element of the profit vector (PRO_t) by the sum assured S. This normalises cashflows so products with different benefit levels can be compared on equal terms. It shows the profit (positive or negative) per £1 of cover, making it easier to identify structurally loss-making product designs.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the profit signature and explain how it is derived from the profit vector.',a:'The profit signature Π_t = PRO_t × (probability of being in force at start of year t). For a whole-life policy: Π_t = PRO_t × ₜ₋₁p_x. It converts per-surviving-policy profits to per-policy-issued profits, allowing NPV and IRR calculations as cashflows from the policyholder\'s issue date.'},
  {module:'CM1B',sub:'res-reserve',color:'#3D6FD1',topic:'Pricing & reserving',q:"What is Zillmer's method?",a:"Zillmer's adjustment modifies the net premium reserve to allow for heavy initial expenses (e.g. first-year commission). The Zillmer reserve = net premium reserve − α·(1 − A_{x+t:n−t|}), where α is the Zillmer adjustment (proportional to the initial expense). Early reserves become lower (or negative), repaid by an augmented net premium in later years. Negative reserves must be zeroed."},
  {module:'CM1B',sub:'res-grossprem',color:'#3D6FD1',topic:'Pricing & reserving',q:'Why can gross premium reserves be negative in early policy years, and why does this matter?',a:'Large initial expenses (commission, setup costs) mean the EPV of future outgo is less than the EPV of future premiums in early years, giving a negative reserve. Regulators prohibit negative reserves, so they are set to zero (zeroised); any resulting financing cost must be included in the premium or borne by the insurer as a capital strain.'},
  {module:'CM1B',sub:'res-mortality',color:'#3D6FD1',topic:'Pricing & reserving',q:'What is the net amount at risk (NAAR)?',a:'NAAR = S − ₜV, the death benefit less the reserve held at the start of the policy year. The reserve is already set aside to help pay the claim; the insurer is exposed only to the difference. NAAR is used in computing the expected mortality cost: E[cost] = q_{x+t} × NAAR, and in analysing mortality profit.'},
  {module:'CM1B',sub:'res-unitlinked',color:'#3D6FD1',topic:'Pricing & reserving',q:'Distinguish the unit reserve from the non-unit reserve for a unit-linked contract.',a:'Unit reserve: the market value of units held in the policyholder\'s fund — it fluctuates with markets and belongs economically to the policyholder. Non-unit (sterling) reserve: the insurer\'s own reserve for future negative non-unit cashflows (e.g. top-up death benefit, expenses exceeding fund charges). Total gross premium reserve = unit reserve + non-unit reserve.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'What is the internal rate of return (IRR) in profit testing and how is it used?',a:'The IRR is the risk discount rate at which the NPV of the profit signature equals zero. If IRR > required risk discount rate (hurdle rate), the product earns a sufficient return on capital. It is used alongside profit margin (NPV of profit / EPV of premiums) and payback period to assess product profitability.'},
  {module:'CM1B',sub:'res-profit',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the profit margin in life insurance profit testing.',a:'Profit margin = NPV(profit signature) / EPV(premiums), both discounted at the risk discount rate. A positive profit margin means the product earns more than the cost of capital; it expresses profit as a fraction of premium income, enabling comparison across products of different premium sizes and contract lengths.'},

  // ── CS1B R-IMPLEMENTATION FLASHCARDS ─────────────────────────────────────
  {module:'CS1B',sub:'cs1b-reg-lm',color:'#2E9C8E',topic:'R: Fitting lm()',q:'How do you fit a linear regression in R and inspect the results?',a:'model <- lm(y ~ x1 + x2, data=df). Then summary(model) prints coefficients, SEs, t-values, p-values, R², and the F-statistic. coef(model) extracts the coefficient vector. Use confint(model) for 95% confidence intervals on coefficients.'},
  {module:'CS1B',sub:'cs1b-reg-lm',color:'#2E9C8E',topic:'R: Extracting model statistics',q:'How do you extract R², residual SE, and coefficient p-values from a fitted lm() in R?',a:'s <- summary(model). Then: R² = s\\$r.squared; adjusted R² = s\\$adj.r.squared; RSE = s\\$sigma; coefficient table (incl. p-values) = coef(s) or s\\$coefficients. The p-value for coefficient j is s\\$coefficients[j, "Pr(>|t|)"].'},
  {module:'CS1B',sub:'cs1b-reg-lm',color:'#2E9C8E',topic:'R: predict()',q:'How do you use predict() to get fitted values and intervals from an lm() model?',a:'predict(model, newdata=df_new) for point predictions on new data. Add interval="confidence", level=0.95 for a CI on the conditional mean E[Y|X]. Add interval="prediction" for a PI on a single new observation — always wider because it adds σ² to the variance of the estimate.'},
  {module:'CS1B',sub:'cs1b-reg-glm',color:'#2E9C8E',topic:'R: Fitting glm()',q:'How do you fit a Poisson GLM with a log-link and exposure offset in R?',a:'model <- glm(claims ~ x1 + x2, family=poisson(link="log"), offset=log(exposure), data=df). The offset adjusts for differing exposure so the response is modelled as a rate. exp(coef(model)) converts log-scale coefficients to multiplicative rate ratios. summary(model) shows deviance and AIC.'},
  {module:'CS1B',sub:'cs1b-reg-glm',color:'#2E9C8E',topic:'R: Comparing nested GLMs',q:'How do you compare two nested GLMs in R?',a:'anova(model_small, model_large, test="Chisq") performs a likelihood ratio test: the deviance difference ~ χ²(Δdf) under H₀. Alternatively, AIC(model) or BIC(model) for information criteria — lower is better. For non-nested models use AIC/BIC only; LRT (anova) requires one model to be a special case of the other.'},
  {module:'CS1B',sub:'cs1b-reg-diag',color:'#2E9C8E',topic:'R: Regression diagnostics',q:'How do you produce and interpret the 4 standard diagnostic plots for a linear model in R?',a:'par(mfrow=c(2,2)); plot(model). Four plots: (1) Residuals vs Fitted — checks linearity and homoscedasticity (want random scatter). (2) Normal Q-Q — checks normality of residuals (want points on diagonal). (3) Scale-Location — homoscedasticity (want flat line). (4) Residuals vs Leverage — identifies influential points via Cook\'s distance.'},
  {module:'CS1B',sub:'cs1b-inf-test',color:'#2E9C8E',topic:'R: t.test()',q:'How do you run one-sample and two-sample t-tests in R?',a:'One-sample: t.test(x, mu=mu0). Two-sample: t.test(x, y) (Welch, default) or t.test(x, y, var.equal=TRUE) (equal variances). One-sided: alternative="greater" or "less". Result includes t-statistic, df, p-value, and 95% CI. Access: result\\$p.value, result\\$conf.int.'},
  {module:'CS1B',sub:'cs1b-inf-test',color:'#2E9C8E',topic:'R: chisq.test()',q:'How do you run a chi-squared goodness-of-fit test in R?',a:'chisq.test(observed, p=expected_probs) where expected_probs sums to 1. The function returns X², df = k−1 (minus estimated parameters), and a p-value. Cells with expected counts < 5 should be merged first. For a contingency table use chisq.test(table) with no p= argument.'},
  {module:'CS1B',sub:'cs1b-rv-dist',color:'#2E9C8E',topic:'R: Distribution functions',q:'What is the d/p/q/r naming convention for distributions in R?',a:'For any distribution XYZ: dxyz(x,...) is the density/PMF; pxyz(q,...) is the CDF P(X≤q); qxyz(p,...) is the quantile (inverse CDF); rxyz(n,...) simulates n random values. Examples: dnorm/pnorm/qnorm/rnorm (Normal), dpois/ppois/qpois/rpois (Poisson), dgamma/pgamma/qgamma/rgamma (Gamma), dbeta/pbeta/qbeta/rbeta (Beta).'},
  {module:'CS1B',sub:'cs1b-rv-dist',color:'#2E9C8E',topic:'R: Poisson distribution',q:'How do you simulate from and compute probabilities for a Poisson distribution in R?',a:'rpois(n, lambda) simulates n values. dpois(k, lambda) gives P(X=k). ppois(q, lambda) gives P(X≤q). Example: P(X=3 | λ=2) = dpois(3,2) ≈ 0.180. To test if data is Poisson: check mean ≈ var (dispersion test: var(x)/mean(x) near 1) and use chisq.test() for a formal goodness-of-fit test.'},

  // ── Extra revision cards ──
  // CS1A — Data analysis
  {module:'CS1A',sub:'data-explore',color:'#2E9C8E',topic:'Data analysis',q:'State one advantage of the IQR over the variance as a measure of spread.',a:'The IQR is resistant to outliers and skew. Variance is inflated by extreme values because deviations are squared.'},
  {module:'CS1A',sub:'data-pca',color:'#2E9C8E',topic:'Data analysis',q:'What does "reducing dimensionality" mean in PCA?',a:'Replacing p original correlated variables with k < p uncorrelated principal components that retain most of the variance. PC1 captures the most variance, PC2 the next most, and so on.'},
  {module:'CS1A',sub:'data-pca',color:'#2E9C8E',topic:'Data analysis',q:'A PCA gives PC1 explaining only 29% of variance. What does this mean practically?',a:'No single component dominates — the variables are largely uncorrelated with each other. PCA offers limited dimensionality-reduction benefit: you would need most components to capture sufficient variance, so the original variables are already relatively independent.'},
  // CS1A — Random variables
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'Write down the PDF and CDF of an Exponential(λ) distribution.',a:'PDF: f(x) = λe^(−λx), x > 0. CDF: F(x) = 1 − e^(−λx), x > 0. The CDF is the integral of the PDF — not the same thing.'},
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'State the three conditions required for a counting process to be a Poisson process.',a:'(1) Stationarity — events occur at constant rate λ; probability depends only on interval length, not when it starts. (2) Independence — events in non-overlapping intervals are independent. (3) Orderliness — the probability of two or more simultaneous events is negligible.'},
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'In the inverse transform method, do you invert the PDF or the CDF? Why?',a:'The CDF. The CDF maps x → [0,1], so its inverse maps a uniform u back to x. This works because F(X) ~ U(0,1) for any continuous X — the probability integral transform.'},
  {module:'CS1A',sub:'rv-joint',color:'#2E9C8E',topic:'Random variables',q:'What is the difference between the marginal PDF of X and the conditional PDF of X given Y?',a:'Marginal f_X(x) = ∫f(x,y)dy — the distribution of X with Y eliminated entirely. Conditional f_{X|Y}(x|y) = f(x,y)/f_Y(y) — the distribution of X given a specific value of Y.'},
  {module:'CS1A',sub:'rv-joint',color:'#2E9C8E',topic:'Random variables',q:'State the formal condition for independence of X and Y in terms of their distributions.',a:'f(x,y) = f_X(x)·f_Y(y) — the joint equals the product of the marginals. Also requires rectangular support (the range of X must not depend on Y and vice versa).'},
  {module:'CS1A',sub:'rv-condexp',color:'#2E9C8E',topic:'Random variables',q:'State the law of total expectation and the law of total variance.',a:'E[X] = E[E[X|Y]] and Var(X) = E[Var(X|Y)] + Var(E[X|Y]).'},
  {module:'CS1A',sub:'rv-condexp',color:'#2E9C8E',topic:'Random variables',q:'S = X₁+...+X_N where N and the Xᵢ are independent. What is E[S]?',a:'E[S] = E[N]·E[X]. Condition on N first: E[S|N=n] = nE[X], then take the expectation over N.'},
  {module:'CS1A',sub:'rv-gf',color:'#2E9C8E',topic:'Random variables',q:'Write the MGF of a continuous random variable X as an integral. What is the common error?',a:'M_X(t) = ∫ e^(tx) · f(x) dx. Common error: putting f(x) inside the exponent → ∫ e^(tx·f(x)) dx. f(x) is a weight, not part of the power.'},
  {module:'CS1A',sub:'rv-clt',color:'#2E9C8E',topic:'Random variables',q:'State the Central Limit Theorem. What two conditions must hold?',a:'If X₁...Xₙ are iid with finite mean μ and finite variance σ², then X̄ ~ N(μ, σ²/n) approximately for large n. Conditions: (1) iid, (2) finite mean and variance.'},
  {module:'CS1A',sub:'rv-clt',color:'#2E9C8E',topic:'Random variables',q:'What are the mean and variance of X̄ for a sample of size n from a population with mean μ and variance σ²?',a:'E[X̄] = μ, Var(X̄) = σ²/n. Divide by n, not √n. The SD of X̄ is σ/√n.'},
  {module:'CS1A',sub:'rv-sampling',color:'#2E9C8E',topic:'Random variables',q:'State two situations where a chi-squared distribution arises naturally in inference.',a:'(1) Goodness-of-fit tests and contingency-table tests. (2) Inference on the variance of a single Normal sample — the test statistic (n−1)S²/σ² ~ χ²(n−1).'},
  {module:'CS1A',sub:'rv-sampling',color:'#2E9C8E',topic:'Random variables',q:'State one situation where an F distribution arises naturally in inference.',a:'Comparing the variances of two independent Normal samples — the test statistic S₁²/S₂² ~ F(n₁−1, n₂−1). Used in var.test() in R.'},
  {module:'CS1A',sub:'rv-sampling',color:'#2E9C8E',topic:'Random variables',q:'How are χ², t and F constructed from standard Normals?',a:'χ²(n) = Z₁²+...+Zₙ² where Zᵢ ~ N(0,1) iid. t(n) = Z/√(χ²(n)/n). F(m,n) = (χ²(m)/m)/(χ²(n)/n). Chain: Normal → χ² → t and F.'},
  // CS1A — Statistical inference
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'What is the moment-based sample variance formula used when deriving method-of-moments estimators?',a:'s² = (1/n)Σxᵢ² − x̄² — i.e. E[X²] minus the squared sample mean. Note this version divides by n, not n−1.'},
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'State four desirable properties of a good estimator.',a:'(1) Unbiasedness — E[θ̂] = θ. (2) Efficiency — smallest possible variance, ideally attaining the Cramér-Rao lower bound. (3) Consistency — θ̂ → θ as n → ∞. (4) Sufficiency — uses all the sample information about θ. MSE = bias² + variance combines bias and efficiency.'},
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'Write the log-likelihood for a random sample from Exponential(λ) and find the MLE.',a:'ℓ(λ) = n·log(λ) − λΣXᵢ. Differentiate: n/λ − ΣXᵢ = 0 → λ̂ = 1/X̄. Don\'t forget the n in front of log(λ).'},
  {module:'CS1A',sub:'inf-est',color:'#2E9C8E',topic:'Statistical inference',q:'In the bootstrap method, are samples taken with or without replacement?',a:'With replacement. This creates variability between resamples. Without replacement you would just return the original dataset.'},
  {module:'CS1A',sub:'inf-ci',color:'#2E9C8E',topic:'Statistical inference',q:'How do you construct a 95% CI using the bootstrap method?',a:'Resample with replacement many times, computing the statistic each time. Take the 2.5th and 97.5th percentiles of the bootstrap distribution as the CI bounds. No assumption about the theoretical sampling distribution is needed.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'What does a 5% significance level mean in terms of Type I error?',a:'P(Type I error) = 0.05 — a 5% probability of rejecting H₀ when it is actually true. It is not 1−0.05, and it does not mean there is a 5% chance you are wrong after rejecting.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'Define the p-value of a hypothesis test.',a:'The probability of observing a test statistic at least as extreme as the one obtained, assuming H₀ is true. A small p-value = data unlikely under H₀ = evidence to reject. It is NOT the probability that H₀ is true.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'When do you reject H₀ in a chi-square test?',a:'When the test statistic exceeds the critical value χ²(α, df). A larger test statistic = a bigger discrepancy between observed and expected = more evidence against H₀.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'State H₀ and H₁ for a chi-square test of independence.',a:'H₀: the two variables are independent (no association). H₁: the two variables are not independent (association exists). H₀ is always the "no relationship" assumption.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'Complete the p-value definition: "The probability of observing a test statistic at least as extreme as the one obtained..."',a:'"...assuming H₀ is true." This phrase is mandatory — without it the definition is incomplete.'},
  // CM1A — Theory of interest rates
  {module:'CM1A',sub:'int-rates',color:'#3D6FD1',topic:'Theory of interest rates',q:'Nominal rate i^(12) = 6% p.a. Find the effective annual rate.',a:'Effective monthly rate = 6%/12 = 0.5%. Effective annual rate = (1.005)^12 − 1 = 6.17%. Formula: i = (1 + i^(p)/p)^p − 1.'},
  {module:'CM1A',sub:'int-rates',color:'#3D6FD1',topic:'Theory of interest rates',q:'Why is the rate of discount d always less than the rate of interest i for the same transaction?',a:'d = i/(1+i). Discount is paid upfront on the full amount lent (£1), while interest is paid at the end on the smaller amount received (£1−d). Same cashflow, different base → d < i.'},
  {module:'CM1A',sub:'int-rates',color:'#3D6FD1',topic:'Theory of interest rates',q:'Show that d = 1−v and state what it means intuitively.',a:'v = 1/(1+i), so 1−v = 1 − 1/(1+i) = i/(1+i) = d. Intuition: v is the PV of £1 in one year, so 1−v is the discount deducted upfront — exactly what d represents.'},
  {module:'CM1A',sub:'int-pv',color:'#3D6FD1',topic:'Theory of interest rates',q:'Two payments are due at different times. How do you find a single equivalent payment at time t?',a:'(1) Find the total PV of all payments at t=0. (2) Accumulate that single PV to time t: X = PV × (1+i)^t. Do not accumulate each payment separately — combine at t=0 first.'},
  {module:'CM1A',sub:'int-pv',color:'#3D6FD1',topic:'Theory of interest rates',q:'Distinguish between the present value and accumulated value of a cashflow stream. Which does an insurer use to price a contract?',a:'PV — discount all cashflows back to t=0. AV — accumulate all cashflows forward to a future date t=n. AV = PV × (1+i)^n. Insurers use PV — they equate the PV of premiums to the PV of expected benefits (equation of value) to set a fair premium.'},
  {module:'CM1A',sub:'int-inf',color:'#3D6FD1',topic:'Theory of interest rates',q:'A payment is described as "£X in today\'s prices" due in n years. What is the nominal cash paid and how do you find the PV?',a:'Nominal cash = X × (1+f)^n (inflate — nominal is always bigger than real). PV = nominal cash / (1+i)^n. Or shortcut: PV = X / (1+i\')^n directly.'},
  {module:'CM1A',sub:'int-inf',color:'#3D6FD1',topic:'Theory of interest rates',q:'State the exact formula for the real rate of interest i\' given nominal rate i and inflation f.',a:'1 + i\' = (1+i)/(1+f), so i\' = (1+i)/(1+f) − 1. The approximation i−f works for small rates only — always use the exact formula in the exam.'},
  {module:'CM1A',sub:'int-inf',color:'#3D6FD1',topic:'Theory of interest rates',q:'An investor needs a real return of i\' with inflation f. What nominal rate must they achieve?',a:'(1+i) = (1+i\')(1+f), so i = (1+i\')(1+f) − 1. This is just the exact formula rearranged.'},
  {module:'CM1A',sub:'int-inf',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is the golden rule when working with real and nominal rates?',a:'Never mix them. Nominal cashflows → discount at the nominal rate. Real cashflows → discount at the real rate. Convert first if needed: real → nominal by multiplying by (1+f)^n.'},
  {module:'CM1A',sub:'int-inf',color:'#3D6FD1',topic:'Theory of interest rates',q:'£10,000 invested for n years at real rate i\'. How do you find the increase in purchasing power?',a:'Real accumulated value = 10,000 × (1+i\')^n. Purchasing-power increase = real accumulated value − 10,000. You must compound over all n years — do not just multiply the rate by the principal.'},
  {module:'CM1A',sub:'int-cashflow',color:'#3D6FD1',topic:'Theory of interest rates',q:'What are the two sources of uncertainty that can affect cashflows in a cashflow model?',a:'(1) Amount — the size of the cashflow may be unknown (e.g. dividends, claim amounts). (2) Timing — when the cashflow occurs may be unknown (e.g. death benefit, insurance claim). Interest rates and inflation affect the value of cashflows when discounting, but are not themselves sources of cashflow uncertainty.'},
  // CS1B — R computing
  {module:'CS1B',sub:'cs1b-rv-dist',color:'#2E9C8E',topic:'R: Random variables',q:'Write R code to generate 500 observations from a Poisson(λ=4) distribution.',a:'rpois(500, lambda=4) — note: the function is rpois not rpoi, and the argument is lambda not rate.'},
  {module:'CS1B',sub:'cs1b-rv-dist',color:'#2E9C8E',topic:'R: Random variables',q:'Write R code to generate 500 observations from a Gamma(shape=3, rate=0.5) distribution.',a:'rgamma(500, shape=3, rate=0.5) — pass n as the first argument directly, don\'t wrap in replicate.'},
  {module:'CS1B',sub:'cs1b-data-explore',color:'#2E9C8E',topic:'R: Data analysis',q:'You want to plot a histogram of a sample and overlay a theoretical curve. What argument must you include in hist() and why?',a:'freq=FALSE — this switches the y-axis from counts to density, so the theoretical curve (which is on a density scale) lines up correctly. Without it the scales don\'t match and the overlay is meaningless.'},
  {module:'CS1B',sub:'cs1b-rv-dist',color:'#2E9C8E',topic:'R: Random variables',q:'What do the d, p, q, r prefix functions return in R?',a:'d = density/PMF at a point. p = cumulative P(X ≤ x). q = quantile (inverse of p). r = random sample. Note: d-functions for continuous distributions return a density, not a probability.'},
  {module:'CS1B',sub:'cs1b-rv-dist',color:'#2E9C8E',topic:'R: Random variables',q:'How do you calculate P(X > 8) for X ~ Binomial(15, 0.4) in R?',a:'1 - pbinom(8, size=15, prob=0.4). P(X > k) = 1 − P(X ≤ k), so k stays as k. Don\'t use k+1 — that gives P(X > k+1) = P(X ≥ k+2).'},

  // ── CM1B decrements 3.1 — Assurance & annuity contract types ──
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What does a whole-life assurance pay, and when?',a:'£1 (or the sum assured) whenever death occurs — no time limit.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What does a term assurance pay?',a:'£1 only if death occurs within n years. Nothing if the person survives past n years.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What does a pure endowment pay?',a:'£1 only if the person survives to the end of n years. Nothing is paid on death.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What does an endowment assurance pay?',a:'£1 on death within n years, OR £1 on survival to n years — whichever happens first.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What is the difference between a whole-life annuity and a temporary annuity?',a:'Whole-life pays for as long as the person lives. Temporary pays for a maximum of n years, stopping earlier if the person dies first.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What is a guaranteed level annuity?',a:'An annuity that pays for a fixed guarantee period regardless of survival, then continues only if the person is still alive.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What is a deferred benefit (annuity or assurance)?',a:'A benefit where payments don\'t start until n years have passed — nothing is paid during the deferred period.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What is a return of premiums annuity or assurance?',a:'A contract where, on death, the premiums paid so far (sometimes with interest) are returned, instead of a fixed sum assured.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What does "joint life" mean for these products?',a:'The contract depends on the death or survival of two (or more) lives together, rather than a single individual.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'In notation, where does the superscript "1" go to indicate a death-triggered payment vs a survival-triggered payment?',a:'Above the age (x) = triggered by death. Above the term (n) = triggered by survival.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'How are profits distributed in a conventional with-profits contract?',a:'Through regular reversionary bonuses (added during the policy term) and a terminal bonus (paid at the end).'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'Once a reversionary bonus is added to a with-profits policy, can it be taken away?',a:'No — once added, reversionary bonuses are guaranteed and cannot be removed.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'In a unit-linked contract, how is the death benefit usually expressed?',a:'As a combination of an absolute (fixed) amount plus a value linked to the unit fund.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'In an accumulating with-profits contract (monetary fund version), how does the fund grow?',a:'Through regular guaranteed interest, bonus interest additions, and a terminal bonus. No explicit charges.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'In a unitised with-profits contract, how does the fund grow?',a:'Through bonus additions (via unit price increases or extra unit allocations) plus a terminal bonus. Subject to explicit charges.'},
  {module:'CM1B',sub:'dec-contracts',color:'#3D6FD1',topic:'Decrement models',q:'What is the key structural difference between conventional with-profits and unitised with-profits?',a:'Conventional = fund defined in monetary terms, no explicit charges. Unitised = fund defined via unit values, has explicit charges.'},
  // ── CM1B decrements 3.2 — Life table functions & survival probabilities ──
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What does lₓ represent?',a:'The number of people (from an original cohort) still alive at age x.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What does dₓ represent, and how is it calculated?',a:'The number of deaths between age x and x+1. Formula: dₓ = lₓ − lₓ₊₁.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What does l₍ₓ₎₊ᵣ mean?',a:'The number alive at age x+r for a life that was medically selected (underwritten) at age x, r years ago.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'Why might a "select" life have a lower mortality rate than an "ultimate" life of the same age?',a:'Because they were recently medically underwritten, so they are temporarily healthier than the general population of that age.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What does ₙpₓ mean?',a:'The probability that a life aged x survives to age x+n.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What does ₙqₓ mean?',a:'The probability that a life aged x dies before reaching age x+n.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What does ₙ|qₓ mean?',a:'The probability that a life aged x survives n years, then dies in the following year (between age x+n and x+n+1).'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What does ₙ|ₘqₓ mean?',a:'The probability that a life aged x survives n years, then dies within the following m years.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'If there is no number written on the left of p or q (e.g. just pₓ), what does that mean?',a:'It means n = 1 — i.e. survival or death within exactly one year.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'What do ₙp₍ₓ₎₊ᵣ and ₙq₍ₓ₎₊ᵣ represent?',a:'The same survival/death probabilities as ₙpₓ and ₙqₓ, but for a life selected at age x, r years ago.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'Write ₙpₓ in terms of lₓ.',a:'ₙpₓ = lₓ₊ₙ / lₓ.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'Write ₙqₓ in terms of lₓ.',a:'ₙqₓ = (lₓ − lₓ₊ₙ) / lₓ.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'Write ₙ|qₓ in terms of lₓ.',a:'ₙ|qₓ = (lₓ₊ₙ − lₓ₊ₙ₊₁) / lₓ.'},
  {module:'CM1B',sub:'dec-life',color:'#3D6FD1',topic:'Decrement models',q:'Write ₙ|ₘqₓ in terms of lₓ.',a:'ₙ|ₘqₓ = (lₓ₊ₙ − lₓ₊ₙ₊ₘ) / lₓ.'},
  // ── CM1B decrements 3.3 — Assurance/annuity factors & present values ──
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What does the symbol Aₓ represent?',a:'The expected present value (EPV) of £1 payable whenever a life aged x dies (whole-life assurance).'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What does äₓ represent, and what do the two dots mean?',a:'The EPV of a whole-life annuity of £1 a year, paid in advance. The two dots mean "in advance" — paid at the start of each year.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What does a bar over a symbol mean (e.g. Āₓ or āₓ)?',a:'The payment is continuous, not annual.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What does the superscript (p) mean, e.g. äₓ⁽ᵖ⁾?',a:'The payment is made pthly — p times per year (e.g. monthly if p=12) — rather than once a year.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'As p increases toward infinity, what does the pthly annuity approach?',a:'The continuous annuity — continuous is the limiting case of pthly.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What does A[x]+r mean?',a:'The assurance factor for a life selected at age x, now r years into the select period.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is the relationship between äₓ and aₓ (whole life)?',a:'äₓ = 1 + aₓ (the advance annuity pays one extra payment upfront at time 0).'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is the relationship for temporary annuities between advance and arrear?',a:'ä(x:n) = 1 + a(x:n−1) — note the term shortens by 1 on the arrear side.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'How does a whole-life annuity split into temporary + deferred?',a:'äₓ = ä(x:n) + ₙ|äₓ (temporary for the first n years, deferred for after).'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'Rearrange to find the deferred annuity formula.',a:'ₙ|äₓ = äₓ − ä(x:n).'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is the alternative way to calculate a deferred annuity, using discounting?',a:'ₙ|äₓ = ₙEₓ × äₓ₊ₙ, where ₙEₓ = vⁿ × ₙpₓ (the pure endowment factor).'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What does ₙEₓ represent in plain English?',a:'The expected present value of £1 paid in n years, only if the person is still alive to receive it.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'Write the equation of value linking Aₓ and äₓ.',a:'Aₓ = 1 − d·äₓ.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'Rearrange to find äₓ in terms of Aₓ.',a:'äₓ = (1 − Aₓ) / d.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is the continuous version of this equation of value?',a:'Āₓ = 1 − δ·āₓ (uses the force of interest δ instead of the discount rate d).'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is the pthly version of this equation of value?',a:'Aₓ⁽ᵖ⁾ = 1 − d⁽ᵖ⁾·äₓ⁽ᵖ⁾ (uses d⁽ᵖ⁾, the pthly discount rate).'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'Write the present value random variable Z for a whole-life assurance (paid at end of year of death).',a:'Z = v^(Kₓ+1), where Kₓ is the curtate future lifetime.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'What is the variance formula for Z (whole-life assurance)?',a:'Var(Z) = ²Aₓ − (Aₓ)² — where ²Aₓ is the assurance factor calculated using v² (double force of interest). Remember to SQUARE Aₓ.'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'How do you get the annuity present value random variable Y from Z, and what is Var(Y)?',a:'Y = (1−Z)/d. Var(Y) = Var(Z) / d².'},
  {module:'CM1B',sub:'dec-meanvar',color:'#3D6FD1',topic:'Decrement models',q:'How do you find the expected accumulated value of a contract at time n, given its EPV?',a:'Multiply the EPV by (1+i)ⁿ. No new formula — just roll the present value forward using compound interest.'},

  // ── CS1B (R) — cards for previously-uncovered subtopics ──
  {module:'CS1B',sub:'cs1b-data-aims',color:'#2E9C8E',topic:'R: Reproducible analysis',q:'How do you make an R analysis reproducible?',a:'set.seed(n) before any random step so simulations repeat exactly. Keep the workflow in a script (not the console), load data with a relative path, and record package versions with sessionInfo(). Reproducibility means anyone re-running the script gets identical output.'},
  {module:'CS1B',sub:'cs1b-data-corr',color:'#2E9C8E',topic:'R: Correlation',q:'How do you compute and test a correlation in R?',a:'cor(x, y) gives Pearson by default; cor(x, y, method="spearman") for rank correlation. cor.test(x, y) adds a p-value and CI — access them with cor.test(x,y)\\$p.value and cor.test(x,y)\\$conf.int. cor(df) returns the full correlation matrix.'},
  {module:'CS1B',sub:'cs1b-data-pca',color:'#2E9C8E',topic:'R: PCA',q:'How do you run and interpret PCA in R?',a:'p <- prcomp(X, scale.=TRUE) — always scale. so variables with large units do not dominate. summary(p) shows the proportion of variance explained; screeplot(p) or plot(p) draws the scree plot; p\\$rotation holds the loadings and p\\$x the component scores.'},
  {module:'CS1B',sub:'cs1b-rv-joint',color:'#2E9C8E',topic:'R: Joint distributions',q:'How do you estimate a joint or marginal relationship from simulated data in R?',a:'Simulate the pair, then table(x, y)/n approximates the joint PMF and rowSums()/colSums() give the marginals. For continuous data use kde2d() (MASS) or a 2D histogram; colMeans() and cov() summarise the means and the covariance matrix.'},
  {module:'CS1B',sub:'cs1b-rv-condexp',color:'#2E9C8E',topic:'R: Conditional expectation',q:'How do you verify E[X] = E[E[X|Y]] by simulation in R?',a:'Simulate Y, then X given each Y; mean(x) estimates E[X], and tapply(x, y, mean) gives the conditional means E[X|Y]. Averaging those conditional means, weighted by the frequency of each Y, reproduces mean(x) — the tower property.'},
  {module:'CS1B',sub:'cs1b-rv-gf',color:'#2E9C8E',topic:'R: Moments',q:'How do you obtain moments of a distribution numerically in R?',a:'By simulation: draw a large sample and use mean(x^k) for the k-th raw moment. By integration: integrate(function(x) x^k*dnorm(x), -Inf, Inf) for a continuous density. The MGF at t is mean(exp(t*x)) for a simulated sample.'},
  {module:'CS1B',sub:'cs1b-rv-clt',color:'#2E9C8E',topic:'R: Central Limit Theorem',q:'How do you demonstrate the CLT in R?',a:'means <- replicate(10000, mean(rexp(30, 1))) then hist(means, freq=FALSE) and overlay curve(dnorm(x, 1, 1/sqrt(30)), add=TRUE). Even from a skewed Exponential, the sample-mean distribution is approximately Normal(μ, σ²/n).'},
  {module:'CS1B',sub:'cs1b-rv-sampling',color:'#2E9C8E',topic:'R: Sampling distributions',q:'Which R functions generate t, chi-square and F variates?',a:'rt(n, df) for Student t, rchisq(n, df) for chi-square, rf(n, df1, df2) for F. The d/p/q forms give density, CDF and quantiles — e.g. qchisq(0.95, df) is the upper 5% critical value used in a variance test.'},
  {module:'CS1B',sub:'cs1b-inf-est',color:'#2E9C8E',topic:'R: Estimation',q:'How do you find an MLE numerically in R?',a:'Define the negative log-likelihood as a function of the parameters, then minimise it: optim(start, nll, method="BFGS"). The result\\$par holds the MLEs. fitdistr() (MASS) does this directly for standard families, also returning standard errors.'},
  {module:'CS1B',sub:'cs1b-inf-ci',color:'#2E9C8E',topic:'R: Confidence intervals',q:'How do you get a confidence interval in R?',a:'For a mean: t.test(x)\\$conf.int. For a proportion: prop.test(k, n)\\$conf.int. For a non-standard statistic, bootstrap it: bm <- replicate(10000, mean(sample(x, replace=TRUE))); quantile(bm, c(0.025, 0.975)).'},
  {module:'CS1B',sub:'cs1b-reg-glmfit',color:'#2E9C8E',topic:'R: GLM deviance',q:'How do you read and compare GLM deviance in R?',a:'summary(model) prints the null and residual deviance; a big drop means the covariates help. Compare nested GLMs with anova(m1, m2, test="Chisq") — the deviance difference is χ² on the extra df. A lower AIC(model) indicates a better trade-off of fit and complexity.'},
  {module:'CS1B',sub:'cs1b-bayes-ci',color:'#2E9C8E',topic:'R: Credible intervals',q:'How do you compute a credible interval from a posterior in R?',a:'With a conjugate posterior use the quantile function directly — e.g. Gamma posterior: qgamma(c(0.025, 0.975), alpha_post, beta_post). From posterior samples, quantile(post, c(0.025, 0.975)) gives the equal-tailed 95% credible interval.'},
  {module:'CS1B',sub:'cs1b-bayes-cred',color:'#2E9C8E',topic:'R: Credibility',q:'How do you compute a Bühlmann credibility premium in R?',a:'Z <- n/(n + k), where k = (expected process variance)/(variance of the hypothetical means); then premium <- Z*mean(x) + (1-Z)*mu. Estimate the components from group means and within-group variances via tapply(x, group, mean) and tapply(x, group, var).'},

  // ══════════════════════════════════════════════════════════════════════════
  // POOL EXPANSION — every card checked against the IFoA 2026 CM1/CS1/CB1 syllabi
  // ══════════════════════════════════════════════════════════════════════════

  // ── CM1 · Theory of interest rates ──
  {module:'CM1A',sub:'int-tvm',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is the difference between simple and compound interest on capital C over n years at rate i?',a:'Simple: accumulated value = C(1 + n·i) — interest is always calculated on the original capital only. Compound: C(1 + i)^n — interest is earned on accumulated interest too. Compound exceeds simple for all n > 1.'},
  {module:'CM1A',sub:'int-tvm',color:'#3D6FD1',topic:'Theory of interest rates',q:'Accumulate £2,000 for 3 years at 4% p.a. effective compound interest.',a:'2000 × (1.04)^3 = 2000 × 1.124864 = £2,249.73. To discount a value back instead, divide by (1.04)^3.'},
  {module:'CM1A',sub:'int-force',color:'#3D6FD1',topic:'Theory of interest rates',q:'The force of interest is δ(t) = 0.05 + 0.01t. Find the accumulation factor from time 0 to 5.',a:'exp(∫₀⁵ (0.05 + 0.01t) dt) = exp([0.05t + 0.005t²]₀⁵) = exp(0.25 + 0.125) = exp(0.375) ≈ 1.4550.'},
  {module:'CM1A',sub:'int-ann',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is an increasing annuity (Ia)_n (payments 1, 2, …, n in arrear) and its formula?',a:'It pays 1 at the end of year 1, 2 at the end of year 2, …, n at the end of year n. (Ia)_n = (ä_n − n·v^n)/i, where ä_n is the annuity-due factor and v = 1/(1+i).'},
  {module:'CM1A',sub:'int-term',color:'#3D6FD1',topic:'Theory of interest rates',q:'What is the difference between a spot rate and a forward rate?',a:'A spot rate s_t is the yield on money invested now and repaid at time t. A forward rate f_{t,r} is the rate agreed now for a loan starting at future time t for r years. The spot accumulation equals the product of the intervening one-year forward accumulations.'},
  {module:'CM1A',sub:'int-term',color:'#3D6FD1',topic:'Theory of interest rates',q:'Name three theories that explain the shape of the yield curve.',a:'(1) Expectations theory — long rates reflect expected future short rates. (2) Liquidity preference — investors demand a premium for locking money away longer, raising long rates. (3) Market segmentation — supply and demand in each maturity band set rates independently.'},
  {module:'CM1A',sub:'int-term',color:'#3D6FD1',topic:'Theory of interest rates',q:'Define the yield to maturity (redemption yield) of a bond.',a:"The single constant interest rate at which the present value of all the bond's future coupons and its redemption payment equals its current market price — i.e. the internal rate of return from buying now and holding to redemption."},

  // ── CM1 · Equation of value ──
  {module:'CM1A',sub:'eqv-basic',color:'#3D6FD1',topic:'Equation of value',q:'What two conditions ensure an equation of value has a unique positive solution for i?',a:'A unique rate exists when the net cashflows change sign only once (all outgo before all income, or vice versa), so the present value is a strictly monotonic function of i. Multiple sign changes can give several solutions or none.'},

  // ── CM1 · Decrement & multiple-life models ──
  {module:'CM1B',sub:'dec-multi',color:'#3D6FD1',topic:'Decrement models',q:'What is the joint-life status (xy) and when does it fail?',a:'The joint-life status survives while BOTH lives are alive and fails on the FIRST death. For independent lives ₙp_xy = ₙp_x · ₙp_y, and the joint-life annuity ä_xy pays only while both survive.'},
  {module:'CM1B',sub:'dec-multi',color:'#3D6FD1',topic:'Decrement models',q:'How do you value a last-survivor annuity over two lives?',a:'By inclusion–exclusion: ä_{last survivor} = ä_x + ä_y − ä_xy. Payment continues while at least one life survives, so add the two single-life values and subtract the joint-life value (counted twice).'},
  {module:'CM1B',sub:'dec-markov',color:'#3D6FD1',topic:'Decrement models',q:'What is a transition intensity μ_x^{ij} in a multiple-state model?',a:'The instantaneous rate of moving from state i to state j at age x — the continuous-time analogue of a transition probability. Probabilities of being in each state over time come from solving the Kolmogorov equations built from these intensities.'},
  {module:'CM1B',sub:'dec-markov',color:'#3D6FD1',topic:'Decrement models',q:'What defines the "Markov" property in a multiple-state model?',a:'Future transitions depend only on the CURRENT state (and age), not on how or when the process arrived there. This memorylessness lets transition intensities depend on current state and age alone.'},
  {module:'CM1B',sub:'dec-mdt',color:'#3D6FD1',topic:'Decrement models',q:'What is the difference between an independent and a dependent decrement rate?',a:'The independent rate q^{(j)} is the probability of leaving by cause j if it were the ONLY decrement. The dependent rate (aq)^{(j)} is the probability of leaving by cause j when ALL decrements operate together — smaller, because another decrement may remove the life first.'},
  {module:'CM1B',sub:'dec-mdt',color:'#3D6FD1',topic:'Decrement models',q:'With constant forces over the year, how do you get the dependent rate (aq)_x^{(j)}?',a:'(aq)_x^{(j)} = (μ^{(j)}/μ^{(τ)}) · (1 − e^{−μ^{(τ)}}), where μ^{(τ)} = Σ_j μ^{(j)} is the total force of decrement. The total exit probability is split between causes in proportion to their forces.'},

  // ── CM1 · Pricing & reserving ──
  {module:'CM1B',sub:'res-grossprem',color:'#3D6FD1',topic:'Pricing & reserving',q:'Write the gross future loss random variable for a whole-life policy with level annual premium P.',a:'L = S·v^{K+1} + (PV of expenses) − P·ä_{K+1}, where K is the curtate future lifetime and S the sum assured. The gross premium is set so that E[L] = 0 (equivalence principle).'},
  {module:'CM1B',sub:'res-mortality',color:'#3D6FD1',topic:'Pricing & reserving',q:'Define the expected death strain (EDS) over a policy year.',a:'EDS = Σ q_{x+t} × DSAR, summed over the in-force policies — the expected cost of death claims in excess of the reserves released, based on the mortality assumption.'},
  {module:'CM1B',sub:'res-mortality',color:'#3D6FD1',topic:'Pricing & reserving',q:'How is mortality profit calculated and interpreted?',a:'Mortality profit = Expected Death Strain − Actual Death Strain (EDS − ADS). Lighter-than-expected mortality (fewer deaths than assumed) gives a positive mortality profit; heavier mortality gives a loss.'},
  {module:'CM1B',sub:'res-unitlinked',color:'#3D6FD1',topic:'Pricing & reserving',q:'What does "zeroisation" of non-unit cashflows mean?',a:'Setting up non-unit (sterling) reserves, working backwards from the final year, so that every future expected non-unit cashflow is made non-negative. This removes future financing strains caused by projected negative cashflows.'},
  {module:'CM1B',sub:'res-unitlinked',color:'#3D6FD1',topic:'Pricing & reserving',q:'Why can a unit-linked contract have negative non-unit cashflows in later years?',a:"Fund-based charges (a percentage of the unit fund) may fail to cover fixed per-policy expenses, or a guaranteed death benefit may exceed the fund value. Where outgo exceeds the charges taken from the fund, the non-unit cashflow is negative and must be reserved for."},

  // ── CS1 · Data analysis ──
  {module:'CS1A',sub:'data-corr',color:'#2E9C8E',topic:'Data analysis',q:"What does Kendall's tau (τ) measure, and how does it differ from Spearman's coefficient?",a:"Kendall's τ = (C − D)/(½n(n−1)), the excess of concordant over discordant pairs. Like Spearman it measures monotonic association from ranks, but it is based on pairwise concordance rather than squared rank differences and is often preferred for small samples."},
  {module:'CS1A',sub:'data-corr',color:'#2E9C8E',topic:'Data analysis',q:"When should you use a rank correlation (Spearman/Kendall) instead of Pearson's r?",a:"When the relationship is monotonic but not linear, when the data are ordinal, or when outliers or non-normality would distort Pearson's r. Rank methods depend only on ordering, so they resist outliers and any monotonic transformation."},
  {module:'CS1A',sub:'data-aims',color:'#2E9C8E',topic:'Data analysis',q:'Distinguish descriptive, inferential and predictive data analysis.',a:'Descriptive: summarise the data in hand (means, charts). Inferential: draw conclusions about a wider population from a sample (estimation, testing). Predictive: build a model to forecast unseen or future outcomes (e.g. regression).'},

  // ── CS1 · Random variables & distributions ──
  {module:'CS1A',sub:'rv-gf',color:'#2E9C8E',topic:'Random variables',q:'What is the cumulant generating function (CGF) and how do you get the mean and variance from it?',a:"CGF C(t) = ln M(t), the log of the MGF. Then C'(0) = E[X] and C''(0) = Var(X). CGFs of independent variables add, which makes them convenient for sums."},
  {module:'CS1A',sub:'rv-dist',color:'#2E9C8E',topic:'Random variables',q:'What does the negative binomial distribution model, and how does it relate to the Poisson?',a:'It counts the failures before the r-th success in Bernoulli trials; equivalently it is a Poisson whose rate is Gamma-distributed. Its variance exceeds its mean, so it models over-dispersed count data where the Poisson (mean = variance) is too restrictive.'},
  {module:'CS1A',sub:'rv-joint',color:'#2E9C8E',topic:'Random variables',q:'For random variables X and Y, what are E[aX + bY] and Var(aX + bY)?',a:'E[aX + bY] = a·E[X] + b·E[Y] always. Var(aX + bY) = a²·Var(X) + b²·Var(Y) + 2ab·Cov(X,Y); the covariance term vanishes only when X and Y are uncorrelated.'},

  // ── CS1 · Statistical inference ──
  {module:'CS1A',sub:'inf-ci',color:'#2E9C8E',topic:'Statistical inference',q:'What is the difference between a confidence interval and a prediction interval?',a:'A confidence interval estimates the MEAN response E[Y|x₀]. A prediction interval estimates a SINGLE future observation at x₀ and is always wider, because it also includes the individual error variance σ², not just the uncertainty in the fitted mean.'},
  {module:'CS1A',sub:'inf-test',color:'#2E9C8E',topic:'Statistical inference',q:'What is a permutation test?',a:'A non-parametric test that builds the null distribution by repeatedly re-shuffling (permuting) the group labels of the pooled data and recomputing the statistic. The p-value is the fraction of permutations giving a statistic at least as extreme as observed — no distributional assumption is needed.'},

  // ── CS1 · Regression & GLMs ──
  {module:'CS1A',sub:'reg-glmfit',color:'#2E9C8E',topic:'Regression & GLMs',q:'How does an analysis of deviance guide GLM covariate selection?',a:'Add terms one at a time; the drop in deviance for each added term is compared to a χ² distribution on the extra degrees of freedom. A significant drop justifies keeping the term. AIC or BIC can be used similarly, penalising the number of parameters.'},

  // ── CS1 · Bayesian statistics ──
  {module:'CS1A',sub:'bayes-conj',color:'#2E9C8E',topic:'Bayesian statistics',q:'How does the Bayesian point estimate depend on the loss function?',a:'The Bayes estimate minimises expected posterior loss. Under squared-error loss it is the posterior MEAN; under absolute-error loss the posterior MEDIAN; under 0–1 (all-or-nothing) loss the posterior MODE.'},

  // ── CB1 · How corporates are financed ──
  {module:'CB1',sub:'fin-short',color:'#6B5DD3',topic:'Corporate finance',q:'What is factoring as a form of short-term finance?',a:'A company sells its trade receivables to a factor, which advances a large percentage (e.g. 80%) at once and collects the debts. It speeds up cash flow and outsources credit control, but costs more than an overdraft and can signal cash-flow weakness.'},
  {module:'CB1',sub:'fin-short',color:'#6B5DD3',topic:'Corporate finance',q:'What is a bill of exchange?',a:'A short-term written instrument ordering one party to pay a fixed sum at a set future date. The holder can wait for maturity or sell (discount) it for immediate cash. Widely used in trade finance to bridge the gap between delivery and payment.'},
  {module:'CB1',sub:'fin-issue',color:'#6B5DD3',topic:'Corporate finance',q:'What is a rights issue and why do companies use one?',a:'An offer of new shares to EXISTING shareholders in proportion to their holdings, usually at a discount to the market price. It raises equity while preserving ownership proportions and is cheaper to underwrite than a general public offer.'},
  {module:'CB1',sub:'fin-issue',color:'#6B5DD3',topic:'Corporate finance',q:'What is the role of an underwriter in a securities issue?',a:'For a fee, the underwriter agrees to buy any shares not taken up by investors, guaranteeing the company raises the funds it needs. This transfers the risk of under-subscription from the issuer to the underwriter.'},
  {module:'CB1',sub:'fin-instr',color:'#6B5DD3',topic:'Corporate finance',q:'What is a contingent convertible bond (CoCo)?',a:"A subordinated bond that automatically converts to equity (or is written down) when a trigger is breached — typically the issuer's capital ratio falling below a set level. Banks use CoCos to absorb losses and support regulatory capital in stress."},
  {module:'CB1',sub:'fin-capital',color:'#6B5DD3',topic:'Corporate finance',q:'What is a share buyback and how does it differ from a dividend?',a:"A buyback repurchases the company's own shares, cutting the share count and lifting EPS; it is flexible and can be tax-efficient (capital vs income). A dividend signals a commitment to regular income. Both return surplus cash to shareholders."},
  {module:'CB1',sub:'fin-growth',color:'#6B5DD3',topic:'Corporate finance',q:'Why might a company grow organically rather than by acquisition?',a:'Organic growth avoids acquisition premiums, integration risk and culture clashes, and is funded from retained profits. It is usually slower but lower-risk; acquisitions offer faster scale but often destroy value when the acquirer overpays.'},
  {module:'CB1',sub:'fin-growth',color:'#6B5DD3',topic:'Corporate finance',q:'Why might a company divest a subsidiary or business unit?',a:'To refocus on core activities, raise cash, exit underperforming or non-strategic operations, satisfy competition regulators, or realise value where a unit is worth more sold than held within the group (removing a conglomerate discount).'},

  // ── CB1 · Evaluating projects ──
  {module:'CB1',sub:'proj-coc',color:'#6B5DD3',topic:'Evaluating projects',q:"What is the difference between a company's equity beta and asset beta?",a:'The asset (ungeared) beta reflects business risk alone. The equity (geared) beta also reflects financial risk from gearing: β_equity = β_asset × (1 + (1−T)·D/E). More debt raises the equity beta and hence the cost of equity.'},
  {module:'CB1',sub:'proj-coc',color:'#6B5DD3',topic:'Evaluating projects',q:"When is a company's WACC an appropriate discount rate for a project, and when is it not?",a:"WACC is appropriate when the project has the same business risk and gearing as the existing firm. It is inappropriate when the project's risk or financing differs materially — then a project-specific (risk-adjusted) rate should be used instead."},
  {module:'CB1',sub:'proj-npv',color:'#6B5DD3',topic:'Evaluating projects',q:'What are the main methods used to assess the viability of a capital project?',a:'Net present value (NPV — value added, accept if > 0), internal rate of return (IRR — the rate giving NPV = 0), payback period and discounted payback (time to recover the outlay). NPV is theoretically preferred as it measures absolute value created.'},
  {module:'CB1',sub:'proj-cashflow',color:'#6B5DD3',topic:'Evaluating projects',q:"Which cashflows are relevant when estimating a project's cashflows?",a:'Only incremental future cashflows that change because of the project — include opportunity costs and working-capital movements; exclude sunk costs, unchanged allocated overheads, and financing cashflows (captured in the discount rate). Treat tax and inflation consistently.'},

  // ── CB1 · Constructing & interpreting accounts ──
  {module:'CB1',sub:'acc-concepts',color:'#6B5DD3',topic:'Interpreting accounts',q:'State the going concern concept.',a:'Accounts are prepared assuming the entity will continue operating for the foreseeable future, so assets are not valued at forced-sale prices. If going concern does not hold, a break-up basis must be used and disclosed.'},
  {module:'CB1',sub:'acc-concepts',color:'#6B5DD3',topic:'Interpreting accounts',q:'State the prudence and consistency concepts.',a:'Prudence: exercise caution under uncertainty — do not overstate assets or income, nor understate liabilities or losses. Consistency: apply the same policies period to period so results are comparable; any change must be disclosed and justified.'},
  {module:'CB1',sub:'acc-stmts',color:'#6B5DD3',topic:'Interpreting accounts',q:'What does the statement of financial position (balance sheet) show?',a:'A snapshot at one date of what the company owns and owes: assets = equity + liabilities. It reveals financial structure and solvency, unlike the income statement which covers a period of trading.'},
  {module:'CB1',sub:'acc-stmts',color:'#6B5DD3',topic:'Interpreting accounts',q:'How does the cash flow statement differ from the income statement?',a:'The income statement measures profit on an ACCRUALS basis (revenue earned less expenses incurred). The cash flow statement tracks actual CASH moving through operating, investing and financing activities — showing liquidity that accrual profit can hide.'},
  {module:'CB1',sub:'acc-insbank',color:'#6B5DD3',topic:'Interpreting accounts',q:"How does a bank's balance sheet differ from a typical trading company's?",a:'For a bank, customer DEPOSITS are liabilities and LOANS advanced are assets — the reverse of everyday intuition. Banks are highly geared, hold regulatory capital, and their accounts stress liquidity, capital adequacy and credit-loss provisions.'},
  {module:'CB1',sub:'acc-construct',color:'#6B5DD3',topic:'Interpreting accounts',q:'Contrast straight-line and reducing-balance depreciation.',a:"Straight-line charges an equal amount each year: (cost − residual)/useful life. Reducing-balance charges a fixed percentage of the falling carrying amount, giving higher charges early and lower later. Both spread an asset's cost over its useful life (accruals concept)."},

  // ── CS1 (R computing) · targeted gaps ──
  {module:'CS1B',sub:'cs1b-rv-joint',color:'#2E9C8E',topic:'R: Joint distributions',q:'How do you simulate correlated bivariate Normal data in R?',a:'Use MASS::mvrnorm(n, mu, Sigma) with a mean vector mu and covariance matrix Sigma (symmetric, positive-definite). Check the result with cor(sim) and plot(sim); the off-diagonal of Sigma controls the covariance.'},
  {module:'CS1B',sub:'cs1b-inf-ci',color:'#2E9C8E',topic:'R: Confidence intervals',q:'How do you get a confidence interval for a binomial proportion in R?',a:'prop.test(x, n)\\$conf.int gives an approximate (Wilson) 95% interval for the success probability from x successes in n trials; binom.test(x, n)\\$conf.int gives the exact Clopper–Pearson interval.'},
  {module:'CS1B',sub:'cs1b-reg-glmfit',color:'#2E9C8E',topic:'R: GLM output',q:'How do you extract fitted values and residuals from a glm() in R?',a:'fitted(model) returns fitted means on the response scale; residuals(model, type="deviance") and residuals(model, type="pearson") give the two diagnostic residual types; predict(model, newdata, type="response") predicts on new data.'},
];

const CARDS = [...CARDS_BASE, ...EXTRA_CARDS];
